-- =====================================================================
-- NutriOn — Descrições breves do catálogo de exercícios (spec DESC-03)
--
-- Gerado por scripts/gerar-seed-descricoes.mjs a partir de
-- scripts/data/descricoes-exercicios.json, revisado antes de virar migration.
-- Para regerar: ajuste o JSON e rode `npm run gerar:seed-descricoes`.
--
-- Casa por (grupo, nome) — a unique do catálogo desde 20260420120000. Id de
-- banco não serviria: o JSON precisa sobreviver a um reseed do catálogo.
--
-- IDEMPOTENTE: só preenche onde description is null. Rodar de novo não
-- sobrescreve texto que tenha sido ajustado à mão no banco.
--
-- Total: 521 exercícios.
-- =====================================================================

with novas(grupo_slug, exercicio_nome, descricao) as (
  values
  ('back', 'Alongamento de latíssimo (lat stretch)', 'Em pé, eleve os braços acima da cabeça, entrelace as mãos e incline o tronco lateralmente, sentindo o alongamento na lateral do torso. Erro comum: inclinar o tronco para frente em vez de para o lado.'),
  ('back', 'Alongamento de trapézio', 'Sentado ou em pé, incline a orelha em direção ao ombro e, com a mão oposta, aplique leve pressão para aprofundar o alongamento. Erro comum: puxar com força excessiva, causando tensão.'),
  ('back', 'Barra australiana', 'Segure a barra baixa com pegada supinada, corpo inclinado e reto, puxe o peito até a barra, mantendo os ombros estáveis. Erro comum: balançar o corpo ou usar impulso dos quadris, reduzindo a eficácia do exercício.'),
  ('back', 'Barra fixa (pronada)', 'Segure a barra com as palmas voltadas para frente, ombros retraídos, puxe o peito até a barra e desça controlado. Erro comum: balançar o corpo e usar impulso ao invés de força das costas.'),
  ('back', 'Barra fixa (supinada)', 'Agarre a barra com as palmas voltadas para você, mantenha os cotovelos próximos e eleve o queixo acima da barra, descendo lentamente. Erro comum: abrir os cotovelos e depender só dos bíceps.'),
  ('back', 'Barra fixa assistida com elástico', 'Prenda o elástico na barra, posicione o pé ou joelho no laço e execute o puxão como um pull‑up normal, sentindo a redução de carga. Erro comum: depender demais da assistência e não completar a amplitude total.'),
  ('back', 'Barra fixa com triângulo (V-bar)', 'Segure o V‑bar com as mãos na parte interna, puxe o peito até a barra mantendo o tronco estável e desça de forma controlada. Erro comum: pegada muito estreita que sobrecarrega os punhos e diminui a ativação das costas.'),
  ('back', 'Barra fixa escapular', 'Pendure-se com os braços esticados, contraia e deprime as escápulas para elevar levemente o peito sem dobrar os cotovelos, depois relaxe. Erro comum: dobrar os cotovelos cedo, transformando o movimento em um pull‑up tradicional.'),
  ('back', 'Barra fixa fechada', 'Agarre a barra com as mãos próximas, quase dentro da largura dos ombros, puxe o peito até a barra mantendo os cotovelos ao lado do corpo e desça controlado. Erro comum: abrir os cotovelos ou usar balanço para subir.'),
  ('back', 'Barra fixa pegada larga', 'Posicione as mãos bem mais afastadas que a largura dos ombros, puxe o peito até a barra mantendo os ombros baixos e desça totalmente. Erro comum: largura excessiva que gera desconforto nos ombros e falta de recrutamento dos latíssimos.'),
  ('back', 'Barra fixa pronada', 'Segure a barra pronada, ombros retraídos, eleve o corpo até o peito tocar a barra e retorne de forma controlada. Erro comum: balançar o tronco e usar impulso ao invés de força das costas.'),
  ('back', 'Barra fixa supinada', 'Segure a barra com as palmas viradas para cima, corpo reto, e puxe o peito até a barra, mantendo os cotovelos próximos ao tronco. Erro comum: balançar o corpo ou usar impulso, não completando a amplitude.'),
  ('back', 'Bom dia pernas estendidas (good morning)', 'Fique em pé com a barra sobre os ombros, joelhos levemente flexionados, incline o tronco à frente mantendo a coluna reta até ficar paralelo ao chão, então eleve o tronco; repita. Erro comum: curvar a coluna ou impulsionar com os joelhos.'),
  ('back', 'Child''s pose', 'Ajoelhe‑se, sente‑se sobre os calcanhares, estenda os braços à frente no chão e abaixe a testa, mantendo o tronco relaxado. Erro comum: deixar os joelhos se afastarem demais ou elevar os quadris, reduzindo o alongamento das costas.'),
  ('back', 'Cobra (alongamento)', 'Deite-se de bruços, mãos ao nível do peito; empurre o tronco para cima, arqueando a coluna enquanto os quadris permanecem no chão. Erro comum: elevar os quadris, tirando o foco do alongamento da região lombar.'),
  ('back', 'Deadlift (CrossFit)', 'Comece com os pés na largura dos ombros, barra sobre a metade dos pés; flexione quadris e joelhos, segure a barra com as mãos fora da linha dos joelhos e levante mantendo a coluna neutra até ficar em pé. Erro comum: curvar a lombar ou levantar com os braços, usando força das pernas e quadris.'),
  ('back', 'Encolhimento atrás do corpo (barra)', 'Segure a barra atrás das costas, com as mãos em supinação, eleve os ombros mantendo os braços estendidos e volte controlado. Não deixe a barra deslizar ou use impulso das pernas.'),
  ('back', 'Encolhimento na máquina', 'Ajuste a almofada sobre os ombros, segure as alças e eleve os ombros contra a resistência, retornando devagar. Não bloqueie os cotovelos nem empurre com o tronco.'),
  ('back', 'Encolhimento no cabo', 'Prenda a barra no cabo baixo, fique em pé, segure a barra com as mãos ao lado, eleve os ombros e volte controlado. Não puxe o cabo com os braços; o movimento deve vir dos ombros.'),
  ('back', 'Foam roll lombar', 'Deite-se de costas com o rolo sob a lombar, apoie a cabeça e role delicadamente da região sacral até a altura das costelas. Erro comum: aplicar pressão alta na coluna vertebral.'),
  ('back', 'Levantamento terra (barra)', 'Fique com os pés à largura dos ombros, barra próxima às canelas, agache mantendo a coluna neutra e levante a barra estendendo quadris e joelhos, mantendo-a colada ao corpo. Erro comum: arredondar a lombar ou levantar usando apenas a força dos braços.'),
  ('back', 'Muscle-up', 'Iniciar pendurado na barra, puxar o peito até a barra e, na transição, empurrar a barra acima da cabeça, terminando com os cotovelos estendidos. Erro comum: não completar a transição, ficando preso na barra.'),
  ('back', 'Muscle-up nas argolas', 'Segurar as argolas, puxar o peito até a altura das argolas, fazer a transição empurrando-as para cima e estender os braços, mantendo o corpo alinhado. Erro comum: deixar as argolas balançarem ou perder a rigidez do tronco na transição.'),
  ('back', 'Pull-down (pulley)', 'Sente-se na máquina, segure a barra com as mãos mais largas que os ombros e puxe-a para baixo até a altura do peito, mantendo as costas retas e os cotovelos apontando para baixo. Erro comum: balançar o tronco ou puxar apenas com os braços, tirando o trabalho das costas.'),
  ('back', 'Pulldown de braços retos (barra)', 'Segure a barra com pegada pronada, braços estendidos, e puxe-a em linha reta até a altura do peito, mantendo o tronco estável. Erro comum: curvar a lombar ou usar impulso dos quadris, reduzindo a eficácia do exercício.'),
  ('back', 'Pulldown de braços retos inclinado (cabo)', 'Ajuste o banco inclinado, segure a barra com pegada pronada, braços estendidos, e puxe-a em direção ao peito mantendo o tronco firme. Erro comum: deixar o tronco arquear ou usar impulso, diminuindo a carga nas costas.'),
  ('back', 'Pulldown de braços retos na corda', 'Segure a corda com as mãos em supinação, tronco ereto, puxe a corda para baixo até a altura dos quadris mantendo os braços retos. Erro comum: usar impulso do corpo ou dobrar os cotovelos, reduzindo a carga nas costas.'),
  ('back', 'Puxada atrás (pulley)', 'Sentado, segure a barra com as mãos em supinação, tronco reto, puxe a barra para trás até a altura da cintura, mantendo os cotovelos próximos ao corpo. Erro comum: usar impulso do tronco ou puxar com os braços apenas.'),
  ('back', 'Puxada frontal (pulley)', 'Em pé, segure a barra com as mãos em pronada, tronco firme, puxe a barra para frente até a altura do peito, mantendo os cotovelos alinhados. Erro comum: balançar o corpo ou deixar os ombros subir.'),
  ('back', 'Puxada supinada (pulley)', 'Sente-se, segure a barra com pegada supinada e puxe até o peito, mantendo costas retas e controle na volta. Erro comum: usar impulso do tronco ou curvar a lombar.'),
  ('back', 'Puxada triângulo (pulley)', 'Sente-se, agarre a alça triangular e puxe em direção ao peito, cotovelos próximos ao corpo e peito aberto, controlando o retorno. Erro comum: abrir demais os cotovelos ou puxar com os braços, não com as costas.'),
  ('back', 'Puxada unilateral (pulley)', 'Em pé, segure a alça com uma mão, puxe em linha reta até o lado do tronco mantendo o tronco estável, depois volte controlado. Erro comum: inclinar o tronco ou usar impulso da perna.'),
  ('back', 'Remada alta (halteres)', 'Em pé, segure os halteres, puxe-os verticalmente até o peito com cotovelos apontando para fora, tronco firme, controle na volta. Erro comum: balançar o corpo ou elevar os ombros.'),
  ('back', 'Remada alta com elástico', 'Prenda o elástico ao nível do peito, segure com as duas mãos e puxe-o para cima mantendo cotovelos altos, retornando controlado. Erro comum: deixar o elástico frouxo demais ou usar impulso do tronco.'),
  ('back', 'Remada baixa (pulley)', 'Sente-se no banco, segure a alça do cabo com as mãos em supinação, mantenha costas retas e puxe o cabo até o abdômen, mantendo os cotovelos próximos ao tronco; volte controlado. Erro comum: usar impulso do tronco ou arquear a lombar.'),
  ('back', 'REMADA BAIXA ABERTA', 'Sente-se na máquina, segure as alças laterais com as mãos, mantenha peito aberto e puxe as alças até o nível do peito, contraindo as escápulas; volte de forma controlada. Erro comum: elevar os ombros ao puxar, reduzindo a ativação das costas.'),
  ('back', 'Remada cavalinho', 'Fique em pé, segure a barra fixa à altura da cintura, incline o tronco à frente com joelhos levemente flexionados e puxe a barra até o abdômen, mantendo os cotovelos próximos ao corpo; retorne controlado. Erro comum: balançar o corpo para gerar impulso.'),
  ('back', 'Remada cavalinho unilateral', 'Adote a mesma postura da remada cavalinho, segure a barra com uma mão, mantenha o tronco estável e puxe a barra até o lado do abdômen, controlando a descida; repita do outro lado. Erro comum: girar o tronco ou balançar o corpo.'),
  ('back', 'Remada curvada (barra)', 'Fique em pé, pés na largura dos ombros, joelhos levemente flexionados e tronco inclinado à frente; segure a barra com pegada pronada, puxe até o umbigo mantendo cotovelos próximos ao corpo; volte controlado. Erro comum: arredondar a coluna durante a puxada.'),
  ('back', 'Remada curvada (halteres)', 'Adote postura curvada com joelhos levemente flexionados, segure um haltere em cada mão, puxe-os até o tronco mantendo os cotovelos próximos ao corpo, depois abaixe controlado. Erro comum: deixar os halteres cair ou usar impulso do tronco.'),
  ('back', 'Remada curvada (Smith)', 'Posicione-se curvado, pés firmes, segure a barra da Smith com pegada pronada, puxe-a até o peito mantendo os cotovelos próximos ao corpo, depois retorne controlado. Erro comum: travar os joelhos ou usar o suporte da máquina para impulsionar.'),
  ('back', 'Remada curvada pegada neutra (halteres)', 'Mantenha postura curvada, segure os halteres com pegada neutra (palmas voltadas), puxe-os até o tronco mantendo os cotovelos próximos ao corpo e volte controlado. Erro comum: elevar os ombros ao puxar, diminuindo a ativação das costas.'),
  ('back', 'REMADA CURVADA PRON.', 'Sentado, peito firme, segure a barra pronada e puxe para trás até tocar o tronco, mantendo costas retas. Erro comum: usar impulso dos quadris ou curvar a lombar.'),
  ('back', 'Remada deitado no banco (barra)', 'Deite-se no banco, peito apoiado, segure a barra pronada e puxe em linha reta até o peito, mantendo ombros estáveis. Erro comum: arquear a lombar ou levantar a cabeça.'),
  ('back', 'Remada invertida na fita', 'Debaixo da fita, segure as alças, corpo em linha reta, puxe o peito até a fita, mantendo tronco rígido. Erro comum: deixar quadris caírem ou usar balanço.'),
  ('back', 'Remada máquina', 'Sente-se, pegue as alças, puxe em direção ao abdômen, mantendo costas neutras e cotovelos próximos ao corpo. Erro comum: puxar apenas com os braços, sobrecarregando os ombros.'),
  ('back', 'Remada na máquina articulada', 'Ajuste o assento, segure as alças, puxe em arco até o tronco, mantendo peito para fora e costas retas. Erro comum: usar impulso das pernas ou deixar a carga nos punhos.'),
  ('back', 'Remada na polia alta ajoelhado', 'Ajoelhe-se, segure a barra alta, puxe em direção ao tronco, mantendo costas retas e cotovelos próximos. Erro comum: curvar a lombar ou puxar sem estabilizar o tronco.'),
  ('back', 'Remada no banco inclinado (barra)', 'Deite-se no banco inclinado, segure a barra, puxe em linha reta até o peito, mantendo costas firmes e ombros retraídos. Erro comum: arquear a lombar ou balançar o tronco.'),
  ('back', 'Remada no banco inclinado (halteres)', 'Apoie o peito no banco inclinado, segure os halteres com os braços estendidos e puxe-os em direção ao abdômen, mantendo cotovelos próximos ao tronco. Erro comum: deixar os ombros subir ou usar impulso do tronco.'),
  ('back', 'Remada no trenó', 'Posicione-se atrás do trenó, segure a alça com as mãos à largura dos ombros e puxe o trenó em linha reta até que ele chegue próximo ao peito, mantendo o tronco firme. Erro comum: curvar a lombar ou usar as pernas para impulsionar.'),
  ('back', 'Remada T-bar com triângulo', 'Apoie o peito no apoio, segure o triângulo da barra, puxe em linha reta até que a barra toque o peito, mantendo costas retas. Erro comum: balançar o corpo ou usar impulso dos quadris.'),
  ('back', 'Remada unilateral (halter)', 'Com um joelho e mão apoiados no banco, segure o halter com a outra mão, braço estendido, e puxe o peso em direção ao quadril, mantendo o tronco estável. Erro comum: girar o tronco ou usar impulso do braço.'),
  ('back', 'Remada unilateral (kettlebell)', 'Apoie um joelho no banco, segure o kettlebell com a mão oposta, braço estendido, e eleve o peso até a lateral do tronco, controlando a descida. Erro comum: balançar o corpo ou deixar o cotovelo abrir demais.'),
  ('back', 'Remada unilateral com rotação (cabo)', 'Em pé, segure a alça do cabo com uma mão, puxe em diagonal para trás e para cima, girando levemente o tronco, mantendo o cotovelo próximo ao corpo. Erro comum: mover o tronco excessivamente ou não controlar a volta.'),
  ('back', 'Spinal twist deitado', 'Deite-se de costas, flexione os joelhos e abra os braços em T, deixe os joelhos cair para um lado enquanto gira a cabeça para o lado oposto, mantendo os ombros no chão. Erro comum: mover só a cintura ou levantar os ombros, reduzindo a rotação.'),
  ('back', 'Spinal twist sentado', 'Sente-se com as pernas estendidas à frente, tronco ereto, segure o joelho direito com o braço esquerdo e gire o torso para a esquerda, mantendo a coluna reta. Erro comum: curvar a coluna ou puxar com os braços, diminuindo a torção.'),
  ('back', 'Sumô deadlift high pull', 'Com pés bem afastados e pontas viradas, segure a barra, dobre o quadril e levante a barra até os joelhos, então puxe explosivamente até a altura do peito, mantendo cotovelos altos. Erro comum: curvar a coluna ao levantar ou puxar antes da extensão dos quadris.'),
  ('back', 'Sumô high pull (kettlebell)', 'Posicione os pés afastados, kettlebell entre as pernas, dobre o quadril e, ao estender, puxe o kettlebell até o peito com cotovelos elevados. Erro comum: usar só os braços, sem a extensão completa dos quadris.'),
  ('back', 'Thread the needle', 'Comece em quatro apoios, alinhe o ombro esquerdo sob o quadril direito. Deslize o braço esquerdo por baixo do corpo, girando o tronco e estendendo o braço para cima, depois retorne. Erro comum: deixar o quadril girar demais ou perder a estabilidade da coluna.'),
  ('biceps', 'Alongamento de antebraço (extensor)', 'Estenda o braço à frente, palma para baixo, e use a outra mão para puxar os dedos em direção ao antebraço, sentindo alongamento no dorso. Erro comum: estender demais o cotovelo ou dobrar o pulso.'),
  ('biceps', 'Alongamento de antebraço (flexor)', 'Braço estendido à frente, palma para cima, e use a outra mão para puxar os dedos em direção ao antebraço, alongando a parte interna. Erro comum: flexionar o cotovelo ou aplicar força excessiva nos dedos.'),
  ('biceps', 'Alongamento de bíceps na parede', 'De frente para a parede, coloque a palma da mão contra a parede com o braço estendido, gire o corpo para longe, mantendo o braço reto. Erro comum: inclinar o tronco em vez de girar o corpo, reduzindo o alongamento.'),
  ('biceps', 'Clean bottoms-up (kettlebell)', 'Segure o kettlebell invertido, faça o swing até a posição de rack mantendo a base para cima, e então pressione-o. Erro comum: deixar a base virar para baixo, perdendo controle da alça.'),
  ('biceps', 'Rosca 21 (barra)', 'Segure a barra com pegada supinada, faça 7 repetições da metade inferior, 7 da metade superior e 7 de amplitude completa, controlando o movimento. Erro comum: balançar o tronco ou usar impulso.'),
  ('biceps', 'Rosca alternada (halteres)', 'Em pé, segure os halteres ao lado do corpo e flexione um cotovelo, elevando o peso até a altura do ombro, alternando os braços, mantendo o tronco estável. Erro comum: balançar o corpo ou girar o pulso.'),
  ('biceps', 'Rosca concentrada (halter)', 'Sentado, apoie o cotovelo interno da coxa, segure o haltere e levante apenas o antebraço, controlando a descida. Erro comum: usar o tronco para impulsionar o peso.'),
  ('biceps', 'Rosca concentrada em pé (halter)', 'Em pé, incline levemente o tronco à frente, apoie o cotovelo interno da coxa e levante o haltere, isolando o braço. Erro comum: movimentar o tronco ou usar balanço.'),
  ('biceps', 'Rosca de dedos (barra)', 'Segure a barra com as pontas dos dedos, mantendo os antebraços fixos, e eleve a barra apenas dobrando os dedos até a palma ficar voltada para cima. Erro comum: usar a força da mão inteira ou balançar os cotovelos.'),
  ('biceps', 'Rosca de punho invertida (barra)', 'Apoie os antebraços na bancada, palmas voltadas para baixo, e levante a barra apenas com a flexão dos punhos, mantendo os cotovelos imóveis. Erro comum: envolver os antebraços ou mover os cotovelos.'),
  ('biceps', 'Rosca de punho sentado (barra)', 'Sentado, apoie os antebraços nas coxas com as palmas para cima e eleve a barra usando apenas a flexão dos punhos, mantendo os cotovelos fixos. Erro comum: usar impulso do corpo ou dobrar os cotovelos.'),
  ('biceps', 'Rosca de punho sentado (halteres)', 'Sentado, apoie os antebraços nas coxas, palmas para cima, e levante cada haltere apenas com a flexão dos punhos, mantendo os cotovelos estáveis. Erro comum: rolar os pulsos para trás ou balançar o tronco.'),
  ('biceps', 'Rosca deitado no banco inclinado (barra)', 'Deitado em banco inclinado, segure a barra com as palmas para cima, braços pendentes, e eleve-a dobrando os cotovelos até a altura dos ombros, sem mover o tronco. Erro comum: usar os ombros ou impulsionar o movimento.'),
  ('biceps', 'Rosca deitado supino (halteres)', 'Deitado supino, segure os halteres com as palmas voltadas para cima, braços estendidos, e flexione os cotovelos trazendo-os ao peito, mantendo os ombros firmes. Erro comum: levantar os ombros ou balançar o tronco.'),
  ('biceps', 'Rosca direta (barra)', 'Em pé, segure a barra com pegada supinada, cotovelos próximos ao corpo, e eleve-a até a altura dos ombros, controlando a descida. Erro comum: balançar o tronco ou usar impulso das pernas.'),
  ('biceps', 'Rosca direta (halteres)', 'Em pé, segure um haltere em cada mão, palmas voltadas para cima, e flexione os cotovelos trazendo-os ao peito, mantendo os cotovelos fixos. Erro comum: girar excessivamente os pulsos ou balançar o corpo.'),
  ('biceps', 'Rosca direta (W)', 'Em pé, pés na largura dos ombros, segure a barra em W com pegada supinada, cotovelos fixos ao corpo, levante a barra até a altura dos ombros, controlando a descida. Balançar o tronco ou usar impulso dos quadris é o erro mais comum.'),
  ('biceps', 'ROSCA DIRETA POLIA', 'Em pé, frente à máquina, segure a barra da polia com pegada supinada, cotovelos ao lado, puxe a barra até a altura dos ombros mantendo a postura ereta, volte controlado. Deixar os cotovelos se afastarem do corpo ou puxar com os ombros é o erro frequente.'),
  ('biceps', 'Rosca inclinada (halteres)', 'Deite‑se em banco inclinado, braços pendentes segurando halteres com pegada supinada, eleve os pesos até a altura dos ombros, contraindo o bíceps, depois desça lentamente. O erro comum é balançar o tronco ou usar impulso das costas.'),
  ('biceps', 'Rosca interna sentado (halteres)', 'Sentado, costas retas, segure halteres ao lado do corpo com pegada neutra, flexione os cotovelos trazendo os pesos até a altura dos ombros, mantendo os cotovelos fixos. O erro típico é mover os ombros para frente ou usar impulso do tronco.'),
  ('biceps', 'Rosca inversa (barra)', 'Em pé, pegada pronada (palmas para baixo) na barra, cotovelos ao corpo, levante a barra até a altura dos ombros, controle a descida. Erro comum: curvar as costas ou usar os punhos para puxar.'),
  ('biceps', 'Rosca martelo (halteres)', 'Em pé, segure halteres ao lado do corpo com pegada neutra, eleve‑os mantendo a posição dos punhos paralela ao tronco até a altura dos ombros, desça controlado. O erro mais frequente é girar o punho ou balançar o corpo.'),
  ('biceps', 'Rosca martelo cruzada (halteres)', 'Em pé, segure um haltere em cada mão, cruzando o braço oposto ao subir (punho voltado para o tronco), eleve até a altura do ombro, volte sem cruzar novamente. Erro comum: cruzar demais ou usar impulso dos ombros.'),
  ('biceps', 'Rosca martelo inclinada (halteres)', 'Deite‑se em banco inclinado, halteres ao lado, pegada neutra, eleve os pesos mantendo os punhos paralelos ao tronco até a altura dos ombros, desça lentamente. O erro típico é arquear as costas ou balançar o tronco.'),
  ('biceps', 'Rosca no cabo (pulley)', 'Segure a barra do cabo com as mãos supinadas, pés na largura dos ombros; puxe o cabo flexionando os cotovelos até a altura dos ombros, mantendo o tronco estável. Erro comum: balançar o corpo ou usar impulso dos ombros.'),
  ('biceps', 'Rosca pegada aberta (barra)', 'Fique em pé, segure a barra com as mãos afastadas na largura dos ombros, palmas viradas para cima; eleve a barra flexionando os cotovelos até quase a altura dos ombros, sem mover os cotovelos. Erro comum: fechar demais as mãos ou balançar o tronco.'),
  ('biceps', 'Rosca pegada fechada (barra W)', 'Em pé, segure a barra W com as mãos próximas, palmas voltadas para cima; levante a barra dobrando os cotovelos, mantendo-os próximos ao corpo, até a altura dos ombros. Erro comum: afastar os cotovelos ou usar impulso dos ombros.'),
  ('biceps', 'Rosca Scott (barra)', 'Sente-se no banco Scott, apoie a parte superior dos braços no encosto, segure a barra com pegada supinada; flexione os cotovelos levantando a barra até a contração total, sem mover os ombros. Erro comum: levantar a barra com o tronco ou usar balanço.'),
  ('biceps', 'Rosca Scott (halter)', 'Sente-se no banco Scott, apoie os braços no encosto, segure o haltere com a mão em supinação; eleve o peso flexionando o cotovelo até a contração, mantendo o braço fixo. Erro comum: balançar o corpo ou usar impulso da perna.'),
  ('biceps', 'Rosca Scott unilateral (halter)', 'Sente-se no banco Scott, apoie um braço no encosto, segure o haltere com a mão supinada; levante o peso flexionando o cotovelo até a contração, sem mover o tronco. Erro comum: girar o pulso ou compensar com o outro braço.'),
  ('biceps', 'Rotação de punho (barra)', 'Segure a barra com as mãos em supinação, cotovelos ao lado do corpo; gire os punhos para cima e para baixo, mantendo os antebraços fixos. Erro comum: mover os cotovelos ou usar força dos ombros.'),
  ('cardio', 'Aero jump (cama elástica)', 'Fique em pé na cama elástica, flexione levemente os joelhos e salte explosivamente, aterrissando suavemente e repetindo o ritmo. Erro comum: aterrissar com os joelhos travados ou pular muito alto sem controle.'),
  ('cardio', 'Assault bike', 'Pedale com força mantendo postura ereta, puxando e empurrando as alavancas de forma sincronizada. Erro comum: curvar as costas ou pedalar só com as pernas, comprometendo a eficiência cardio.'),
  ('cardio', 'Bicicleta (ao ar livre)', 'Pedale mantendo postura ereta, mãos no guidão e pedalando em círculo completo, controlando a cadência. Erro comum: inclinar o tronco excessivamente ou pedalar só com os quadris, diminuindo a eficiência.'),
  ('cardio', 'Bicicleta ergométrica', 'Sente-se no selim, ajuste a altura, pedale com força constante mantendo costas retas e ombros relaxados. Erro típico: apoiar o corpo no guidão demais, reduzindo o trabalho das pernas.'),
  ('cardio', 'Caminhada (ao ar livre)', 'Passos confortáveis, postura ereta, braços levemente dobrados, ritmo constante e respiração regular. Erro comum: curvar a coluna ou caminhar com passos muito curtos, reduzindo a eficácia.'),
  ('cardio', 'Corrida (ao ar livre)', 'Mantenha postura ereta, olhar à frente, braços dobrados 90°, passos curtos e cadência constante, pousando no meio do pé. Erro comum: colocar os pés muito à frente, sobrecarregando os joelhos e comprometendo a eficiência da corrida.'),
  ('cardio', 'Crosstrainer', 'Sente-se na máquina, posicione os pés nos pedais e segure os guidões, mova pernas e braços em ritmo circular mantendo a coluna ereta. Erro comum: inclinar demais o tronco ou puxar os guidões com força, diminuindo o trabalho cardiovascular.'),
  ('cardio', 'Double under', 'Salte mantendo o corpo leve, gire a corda duas vezes sob os pés em um único salto, usando principalmente o pulso para acelerar a corda. Erro comum: pular muito alto ou movimentar os braços ao invés dos pulsos, desperdiçando energia.'),
  ('cardio', 'Elíptico', 'Fique em pé na máquina, posicione os pés nos pedais e segure as alças, mova as pernas em círculo simulando corrida enquanto os braços acompanham o movimento. Não segure a respiração nem deixe o tronco inclinar-se para frente.'),
  ('cardio', 'Ergômetro de braço (handbike)', 'Sente-se ou fique em pé, segure as alças, pedale com os braços como se fosse uma bicicleta, mantendo postura ereta. Não segure a respiração nem faça movimentos bruscos que forcem os ombros.'),
  ('cardio', 'Escada / Stair', 'Fique em pé na máquina, segure as alças, suba alternando os pés como se fosse uma escada, mantendo ritmo constante. Erro comum: apoiar o peso excessivamente nas mãos, reduzindo o trabalho das pernas.'),
  ('cardio', 'Esteira (caminhada)', 'Posicione-se centralizado na esteira, mantenha postura ereta, ombros relaxados e caminhe com passos curtos, pousando o calcanhar antes do dedão. Erro comum: inclinar o tronco para frente, sobrecarregando a lombar.'),
  ('cardio', 'Esteira (corrida)', 'Corra na esteira com postura ereta, braços dobrados 90°, impulsione com a perna de trás e aterrisse suavemente na frente, mantendo cadência constante. Erro comum: aterrissar com o calcanhar primeiro, gerando impacto nos joelhos.'),
  ('cardio', 'Fartlek', 'Corra alternando intervalos de ritmo rápido e trote leve, variando a duração conforme o terreno, mantendo postura e respiração controlada. Erro comum: mudar de ritmo de forma abrupta, perdendo o controle da velocidade e aumentando risco de lesão.'),
  ('cardio', 'HIIT', 'Execute séries curtas de exercícios de alta intensidade usando apenas o peso corporal, alternando 30 s de esforço máximo com 15 s de descanso. Erro comum: sacrificar a postura correta quando a fadiga aumenta.'),
  ('cardio', 'Limiar (threshold)', 'Corra em ritmo constante, ligeiramente abaixo do seu limiar anaeróbico, mantendo postura ereta, passadas curtas e respiração regular. Erro comum: acelerar demais e ultrapassar o limiar, causando fadiga precoce.'),
  ('cardio', 'Longão (long run)', 'Corra em ritmo confortável por longa distância, mantendo postura ereta, passadas suaves e respiração cadenciada. Erro comum: iniciar muito rápido, gastando energia e comprometendo o final da corrida.'),
  ('cardio', 'Natação', 'Mantenha o corpo alinhado, braços alternando puxada e recuperação, pernas em batimento constante. Erro comum: prender a cabeça, dificultando respiração e postura.'),
  ('cardio', 'Patinação', 'Fique em pé na máquina de patinação, mantenha os joelhos levemente flexionados e deslize alternando os pés como se estivesse patinando, mantendo o tronco ereto. Erro comum: inclinar o corpo para frente ou usar apenas os quadris, reduzindo a eficácia do exercício.'),
  ('cardio', 'Prowler sprint (trenó)', 'Posicione o trenó à frente, segure as alças, agache levemente e empurre explosivamente para frente, mantendo o tronco reto e passos curtos. Erro comum: curvar a lombar ou usar excessivamente os braços, tirando força das pernas.'),
  ('cardio', 'Pular corda', 'Segure as pontas da corda, mantenha os cotovelos próximos ao corpo, gire a corda com ritmo constante e salte suavemente, aterrissando na ponta dos pés. Erro comum: pular muito alto ou bater os pés no chão, desperdiçando energia.'),
  ('cardio', 'Pular corda (alta intensidade)', 'Segure a corda como no exercício básico, mas aumente a velocidade, mantenha postura ereta, faça pequenos saltos e ritmo rápido. Erro comum: perder a postura, curvar a coluna ou deixar os joelhos colapsarem.'),
  ('cardio', 'Regenerativo', 'Caminhe ou trote levemente ao ar livre, postura ereta, passos curtos e respiração regular. Erro comum: acelerar demais ou deixar os ombros subir.'),
  ('cardio', 'Remo ergômetro', 'Sente-se, segure o guidão, mantenha as costas retas e puxe o cabo em linha reta até o peito, estendendo totalmente na volta. Erro comum: curvar a lombar ou puxar apenas com os braços.'),
  ('cardio', 'Row 500m', 'Ajuste o remo, sente-se com as pernas estendidas, segure a alça, puxe o cabo até o peito mantendo o tronco firme e retorne controlado. Erro comum: arqueamento excessivo das costas ou puxar com os braços sem envolver as costas.'),
  ('cardio', 'Single under', 'Mantenha os pés juntos, segure a corda nas pontas, gire o pulso para que a corda passe por baixo dos pés uma vez a cada salto, mantendo ritmo constante. Erro comum: pular muito alto ou usar os braços em vez dos pulsos, desperdiçando energia.'),
  ('cardio', 'Ski erg', 'Sente-se no aparelho, segure as alças, incline o tronco levemente à frente, puxe alternadamente como se estivesse esquiando, usando braços e tronco, mantendo ritmo. Erro comum: usar só os braços, sem envolver o tronco, ou curvar demais as costas.'),
  ('cardio', 'Spinning (aula)', 'Ajuste o selim, sente-se ereto na bicicleta, pedale mantendo ritmo constante e resistência adequada, mantendo as mãos firmes no guidão e o tronco alinhado. Erro comum: curvar as costas ou segurar o guidão demais, reduzindo a eficácia do pedal.'),
  ('cardio', 'Sprint na esteira', 'Ajuste a inclinação da esteira, inicie em ritmo leve e aumente rapidamente para sprint, mantendo postura ereta, passos curtos e explosivos, pousando na planta do pé. Erro comum: inclinar o tronco para frente ou aterrissar com o calcanhar, reduzindo a velocidade.'),
  ('cardio', 'Stair climber (máquina)', 'Posicione os pés nos pedais, mantenha postura ereta, empurre alternadamente como subir escadas, ritmo constante. Erro comum: inclinar o tronco para frente ou apoiar as mãos excessivamente, reduzindo o trabalho das pernas.'),
  ('cardio', 'Step (aeróbico)', 'Suba e desça de um degrau ou plataforma, alternando os pés, mantendo ritmo e postura ereta, braços ao lado ou em movimento. Erro comum: apoiar peso excessivo no joelho da perna de apoio ou deixar o calcanhar levantar.'),
  ('cardio', 'Subida de escada (ao ar livre)', 'Encare a escada, suba colocando um pé no primeiro degrau e empurre pelo calcanhar, alternando as pernas e mantendo o tronco ereto. Erro comum: usar impulso dos braços ou subir muito rápido, perdendo a postura.'),
  ('cardio', 'Tabata', 'Execute ciclos de 20 segundos de alta intensidade (ex.: burpees, polichinelos) seguidos de 10 segundos de descanso, repetindo por 8 rodadas. Erro comum: não manter a intensidade máxima durante os 20 segundos, reduzindo o efeito cardio.'),
  ('cardio', 'Tiros 400m', 'Corra 400 m mantendo postura ereta, braços relaxados ao lado do corpo e respiração controlada. Mantenha ritmo constante até completar a distância. Erro comum: iniciar muito rápido, o que causa cansaço precoce.'),
  ('cardio', 'Treino intervalado', 'Alterne sprints intensos (ex.: 30 s) com períodos de recuperação ativa (ex.: 60 s de trote ou caminhada), repetindo o ciclo. Mantenha a técnica de corrida durante os esforços. Erro comum: não respeitar o tempo de recuperação, levando a fadiga precoce.'),
  ('cardio', 'Trekking', 'Fique em pé, postura ereta, e caminhe ou corra no equipamento mantendo passos constantes. Erro comum: inclinar o tronco ou segurar a barra demais, comprometendo a postura.'),
  ('cardio', 'Trote leve (esteira)', 'Mantenha postura ereta, passos curtos, pés tocando levemente o tapete e ritmo constante. Erro comum: inclinar o tronco para frente ou bater os pés com força.'),
  ('cardio', 'Versaclimber', 'Segure as alças, mantenha o corpo inclinado e faça movimentos alternados de puxar as pernas e empurrar os braços como escada vertical. Erro comum: usar apenas os braços ou balançar o tronco.'),
  ('chest', 'Alongamento de peito no batente', 'Fique de frente para o batente, apoie os antebraços na moldura na altura dos ombros e dê um passo à frente, sentindo o peito abrir. Erro comum: avançar demais ou elevar os ombros, o que diminui o alongamento.'),
  ('chest', 'Alongamento de peito no chão (cruz)', 'Deite-se de costas no chão, abra os braços formando um T com as palmas voltadas para cima e deixe o peso do corpo abrir o peito. Erro comum: dobrar os cotovelos, o que impede o alongamento completo.'),
  ('chest', 'Crossover alto (cabos)', 'Fique em pé, pés ligeiramente afastados, segure as alças altas dos cabos com braços levemente dobrados e traga-as para baixo e cruzadas na frente do peito, terminando com as palmas voltadas para baixo. Erro comum: usar peso excessivo e travar os cotovelos, limitando a amplitude.'),
  ('chest', 'Crossover baixo (cabos)', 'Posicione-se de frente ao aparelho, segure as alças baixas dos cabos, mantenha braços levemente flexionados e puxe-os em arco diagonal até a altura do peito, cruzando-os à frente. Erro comum: elevar os ombros ou impulsionar o tronco, comprometendo o foco no peito.'),
  ('chest', 'Crossover com elástico', 'Prenda o elástico na parte baixa, segure as pontas, dê um passo à frente mantendo o tronco estável e puxe o elástico em diagonal até a altura do peito, controlando o retorno. Erro comum: balançar o corpo e não controlar a volta, reduzindo a eficácia.'),
  ('chest', 'Crossover unilateral (cabo)', 'Fique lateral ao cabo, segure a alça com a mão oposta, mantenha o tronco firme e puxe o cabo em arco até a linha central do corpo, retornando de forma controlada. Erro comum: girar excessivamente o tronco, perdendo a postura correta.'),
  ('chest', 'Crucifixo cruzado no cabo', 'De pé, segure um cabo em cada mão, braços levemente dobrados, cruze-os à frente do peito em arco controlado e retorne à posição inicial. Erro comum: fechar demais os cotovelos, transformando o movimento em rosca e perder a tensão constante.'),
  ('chest', 'Crucifixo declinado (halteres)', 'Deite-se em banco declinado, segure os halteres acima do peito, abra os braços em arco até sentir alongamento e volte juntando-os. Erro comum: travar os cotovelos ou usar peso que impede a amplitude completa, reduzindo o recrutamento muscular.'),
  ('chest', 'Crucifixo inclinado (halteres)', 'Deite-se em banco inclinado, segure os halteres acima do peito com braços levemente dobrados e abra-os lateralmente até sentir alongamento, depois retorne ao centro. Erro comum: travar os cotovelos ou usar peso excessivo, reduzindo a amplitude.'),
  ('chest', 'Crucifixo inclinado com rotação (halteres)', 'Deite-se em banco inclinado, segure os halteres acima e, ao abrir, gire as palmas para cima; ao fechar, volte à posição neutra. Erro comum: girar demais ou usar impulso, comprometendo o controle do movimento.'),
  ('chest', 'Crucifixo reto (halteres)', 'Deite-se em banco plano, segure os halteres acima do peito com braços levemente dobrados, abra-os lateralmente até sentir alongamento e retorne ao centro. Erro comum: travar os cotovelos ou usar carga excessiva, limitando a amplitude.'),
  ('chest', 'Crucifixo reto unilateral (halteres)', 'Deite-se em banco plano, segure um haltere acima, abra o braço lateralmente mantendo o outro braço ao lado do corpo e volte ao ponto inicial. Erro comum: compensar com o tronco ou usar carga desequilibrada, gerando rotação indesejada.'),
  ('chest', 'Doorway pec stretch', 'Fique em pé na porta, apoie os antebraços na moldura formando 90°, dê um passo à frente até sentir alongamento no peito, mantendo a postura ereta. Erro comum: elevar os ombros ou forçar o alongamento além do limite, gerando desconforto.'),
  ('chest', 'Elevação frontal com pullover (barra)', 'Segure a barra com pegada pronada, braços estendidos à frente; eleve a barra à altura dos ombros, mantendo o tronco estável. Erro comum: usar impulso dos quadris ou elevar a barra acima dos ombros, envolvendo o trapézio.'),
  ('chest', 'Flexão arqueira', 'Comece em posição de flexão, abra as mãos além da largura dos ombros e desloca o peso para um braço enquanto o outro se estende lateralmente, descendo o peito em direção ao braço dobrado. Erro comum: girar o tronco ou perder o alinhamento da coluna.'),
  ('chest', 'Flexão de braço', 'Adote a posição de prancha, mãos na largura dos ombros, baixe o corpo mantendo alinhamento e empurre até estender os braços. Erro comum: deixar os quadris caírem ou subir demais os quadris.'),
  ('chest', 'Flexão declinada', 'Eleve os pés em uma superfície, mãos no chão na largura dos ombros, baixe o peito em linha reta e empurre de volta. Erro comum: elevar os ombros em direção às orelhas ou perder a curvatura natural da coluna.'),
  ('chest', 'Flexão diamante', 'Junte as mãos formando um diamante sob o peito, corpo em linha reta, baixe o peito até quase tocar as mãos e suba estendendo os braços. Erro comum: abrir demais os cotovelos ou deixar os quadris caírem.'),
  ('chest', 'Flexão explosiva', 'Na posição de flexão normal, desça e impulsione o corpo explosivamente para que as mãos saiam do chão, aterrissando suavemente e repetindo. Erro comum: perder controle ao aterrissar, permitindo que os ombros colapsem ou os cotovelos se abram.'),
  ('chest', 'Flexão inclinada', 'Posicione as mãos em um apoio elevado, corpo alinhado, e abaixe o peito até quase tocar a superfície, então empurre para voltar à posição inicial. Erro comum: deixar o quadril cair ou elevar demais, perdendo a linha reta.'),
  ('chest', 'Flexão pegada larga', 'Coloque as mãos bem afastadas no chão, corpo alinhado, abaixe o peito até quase tocar o solo e empurre de volta. Erro comum: deixar o quadril subir ou os ombros colapsarem, reduzindo o trabalho do peito.'),
  ('chest', 'Mergulho em paralelas', 'Segure as barras paralelas, incline o tronco à frente e desça flexionando os cotovelos até o peito quase tocar as barras, suba estendendo os braços. Erro comum: manter o tronco muito vertical, trabalhando mais tríceps que peito.'),
  ('chest', 'Peck deck (máquina)', 'Sente-se, ajuste as alças na altura do peito, junte as almofadas pressionando os cotovelos contra o peito, depois retorne controladamente. Erro comum: deixar os cotovelos subir ou usar impulso, diminuindo a contração do peito.'),
  ('chest', 'Pullover (halter)', 'Deite-se no banco, pés firmes no chão, segure o halter com as duas mãos acima do peito, abra os braços levando o peso atrás da cabeça em arco e volte ao ponto inicial. Erro comum: curvar a coluna ou deixar o peso cair rapidamente.'),
  ('chest', 'Supino declinado (barra)', 'Deite-se no banco declinado, segure a barra com as mãos ligeiramente mais largas que os ombros e empurre-a em linha reta até estender os cotovelos. Erro comum: abrir os cotovelos demais, sobrecarregando os ombros.'),
  ('chest', 'Supino declinado (halteres)', 'Deite-se no banco declinado, segure um haltere em cada mão com as palmas voltadas para os pés e empurre-os simultaneamente, mantendo os braços alinhados ao tronco. Erro comum: deixar os halteres descerem muito abaixo do peito, tensionando os ombros.'),
  ('chest', 'Supino declinado (máquina)', 'Ajuste o assento da máquina de supino declinado, segure as alças e empurre-as para frente até estender os braços, mantendo o tronco firme. Erro comum: usar impulso do corpo, reduzindo a carga nos músculos peitorais.'),
  ('chest', 'Supino declinado (Smith)', 'Posicione-se no banco declinado sob a barra fixa da Smith, segure a barra com pegada larga e empurre-a verticalmente até bloquear os cotovelos. Erro comum: confiar na trajetória guiada e deixar os cotovelos se afastarem, diminuindo a ativação do peito.'),
  ('chest', 'Supino inclinado (barra)', 'Deite-se no banco inclinado, segure a barra com as mãos um pouco mais largas que os ombros e levante-a em linha reta até estender os braços. Erro comum: subir a barra muito alto, envolvendo excessivamente os ombros.'),
  ('chest', 'Supino inclinado (halteres)', 'Deite-se no banco inclinado, segure um haltere em cada mão com as palmas voltadas para dentro e empurre-os para cima, mantendo os cotovelos levemente dobrados. Erro comum: deixar os halteres se aproximarem demais no topo, reduzindo a amplitude.'),
  ('chest', 'Supino inclinado (máquina)', 'Ajuste o assento da máquina de supino inclinado, segure as alças e empurre-as para frente, mantendo o peito firme e os cotovelos em ângulo de 45°. Erro comum: usar impulso das pernas, tirando o foco do peito.'),
  ('chest', 'Supino inclinado no cabo', 'Fique em pé entre dois cabos altos, segure as alças com as mãos na altura do peito e empurre-as para frente, juntando-as à frente do corpo. Erro comum: arquear excessivamente a lombar, sobrecarregando a coluna.'),
  ('chest', 'Supino inclinado pegada neutra (halteres)', 'Deite-se num banco inclinado, segure os halteres com as palmas voltadas uma à outra e empurre-os para cima em linha reta, estendendo os braços, depois desça controlado até tocar o peito. Erro comum: abrir os cotovelos demais, sobrecarregando os ombros.'),
  ('chest', 'Supino no cabo (sentado)', 'Sente-se com as costas firmes, segure as alças do cabo na altura do peito, cotovelos dobrados, e empurre-as para frente até estender totalmente os braços, retornando controlado. Erro comum: usar impulso do tronco, tirando a carga do peito.'),
  ('chest', 'Supino no cabo em pé', 'Fique em pé, pés na largura dos ombros, segure as alças do cabo à altura do peito e empurre-as para frente, estendendo os braços enquanto mantém o tronco estável, retornando com controle. Erro comum: deixar o corpo balançar, comprometendo a postura.'),
  ('chest', 'Supino no solo alternado (kettlebell)', 'Deitado no chão, segure um kettlebell em cada mão, levante um braço enquanto o outro permanece no solo, alternando, mantendo o tronco firme e descendo até o kettlebell tocar o chão. Erro comum: arquear excessivamente a lombar.'),
  ('chest', 'Supino no solo unilateral (kettlebell)', 'Deitado, segure um kettlebell com uma mão, mantenha o outro braço ao lado do corpo, empurre o kettlebell verticalmente até estender o braço e volte controlado. Erro comum: usar impulso do quadril, reduzindo o foco no peito.'),
  ('chest', 'Supino reto (barra)', 'Deitado no banco plano, segure a barra com as mãos ligeiramente mais largas que os ombros, abaixe-a controladamente até o peito e empurre para cima até estender os braços. Erro comum: rebote excessivo da barra no peito, reduzindo o controle.'),
  ('chest', 'Supino reto (halteres)', 'Deite-se no banco, pés firmes no chão, segure os halteres alinhados ao peito e empurre-os verticalmente até estender os braços. Erro comum: deixar os cotovelos abrir demais, sobrecarregando ombros.'),
  ('chest', 'Supino reto (máquina)', 'Sente-se na máquina, ajuste o assento para que as alças fiquem na altura do peito, empurre-as para frente até estender os braços. Erro comum: usar amplitude curta, não completando a extensão total.'),
  ('chest', 'Supino reto com elástico', 'Prenda o elástico atrás das costas, segure as alças na altura do peito e empurre para frente, controlando a resistência na volta. Erro comum: deixar o elástico soltar demais, reduzindo a carga e a estabilidade.'),
  ('chest', 'Supino reto unilateral (halteres)', 'Deite-se no banco, segure um haltere com uma mão na altura do peito, mantenha o tronco estável e empurre o peso verticalmente até estender o braço. Erro comum: girar o tronco ou compensar com o outro lado, perdendo equilíbrio.'),
  ('chest', 'Svend press (anilha)', 'Segure a anilha com as duas mãos na frente do peito, empurre-a para frente estendendo os braços, mantendo os cotovelos levemente flexos. Erro comum: estender demais os cotovelos, transformando em tríceps e tirando foco do peito.'),
  ('chest', 'Wall chest stretch', 'Fique de frente para a parede, coloque as mãos na altura dos ombros e incline o tronco para frente, mantendo o peito aberto. Erro comum: curvar as costas ou deixar os ombros subir, reduzindo o alongamento.'),
  ('core', 'Ab wheel / rodinha', 'Comece ajoelhado, segure a rodinha com as duas mãos, mantenha o tronco alinhado e role para frente estendendo o corpo até quase tocar o chão, depois retorne controlando o movimento. Erro comum: deixar a lombar curvar ou avançar demais, sobrecarregando a coluna.'),
  ('core', 'Abdominal bicicleta', 'Deite-se de costas, coloque as mãos atrás da cabeça, eleve as pernas dobradas e alterne levando o cotovelo direito ao joelho esquerdo e vice‑versa, em movimento de pedal. Erro comum: puxar o pescoço com as mãos ou deixar o tronco girar excessivamente.'),
  ('core', 'Abdominal canivete', 'Deitado, mantenha as pernas estendidas e o tronco reto, eleve simultaneamente pernas e tronco, tentando tocar os dedos dos pés, formando um V, depois volte controlado. Erro comum: usar impulso dos quadris ou deixar a lombar encostar no chão.'),
  ('core', 'Abdominal com braços estendidos', 'Deite-se de costas, braços estendidos acima da cabeça, eleve o tronco e as pernas simultaneamente, tentando tocar as mãos aos pés, mantendo o abdômen contraído. Erro comum: arquear a lombar ou usar impulso dos braços.'),
  ('core', 'Abdominal com joelhos flexionados', 'Deitado, joelhos dobrados, pés no chão, eleve o tronco em direção aos joelhos, contraindo o abdômen, e volte sem perder a tensão. Erro comum: puxar o pescoço com as mãos ou deixar o quadril levantar.'),
  ('core', 'Abdominal com pernas na bola', 'Apoie as pernas sobre a bola suíça, tronco no chão, eleve o tronco em direção às pernas, mantendo o abdômen firme, depois desça controlado. Erro comum: usar impulso da bola ou arquear a lombar.'),
  ('core', 'Abdominal cruzado', 'Deitado, joelhos dobrados, eleve o tronco e toque o cotovelo direito no joelho esquerdo, alternando os lados, mantendo a rotação controlada. Erro comum: puxar a cabeça com as mãos ou fazer a rotação excessiva, sobrecarregando a coluna.'),
  ('core', 'Abdominal declinado', 'Ajuste o banco em declínio, segure a barra ou as mãos atrás da cabeça, eleve o tronco em direção ao peito, mantendo o abdômen contraído, e volte sem usar impulso. Erro comum: balançar o corpo ou deixar a lombar curvar.'),
  ('core', 'Abdominal infra', 'Deitado, pernas estendidas, eleve quadris e tronco, trazendo ombros em direção aos joelhos, mantendo a lombar no chão. Erro comum: usar impulso dos quadris ou arquear a lombar.'),
  ('core', 'Abdominal na bola', 'Sentado na bola suíça, incline o tronco para trás até sentir alongamento, depois eleve o torso contra a gravidade, contraindo o abdômen. Erro comum: apoiar os pés no chão demais, reduzindo a carga.'),
  ('core', 'Abdominal na polia (cable crunch)', 'Ajoelhe-se em frente ao cabo, segure a corda acima da cabeça, flexione o tronco para baixo, trazendo os cotovelos ao quadril, controlando a volta. Erro comum: puxar com os braços, deixando o abdômen relaxado.'),
  ('core', 'Abdominal oblíquo', 'Deitado de costas, flexione joelhos, eleve o tronco girando o cotovelo em direção ao joelho oposto, mantendo o quadril estável. Erro comum: girar demais a cintura, usando impulso.'),
  ('core', 'Abdominal oblíquo declinado', 'Deitado em banco declinado, pés presos, eleve o tronco girando o cotovelo para o joelho oposto, mantendo controle. Erro comum: deixar os ombros subir sem envolver o oblíquo.'),
  ('core', 'Abdominal oblíquo no solo', 'Deitado, pernas dobradas, eleve o tronco e toque o cotovelo no joelho oposto, mantendo o tronco firme. Erro comum: puxar o pescoço com as mãos, reduzindo a ativação.'),
  ('core', 'Abdominal remador', 'Deitado, pernas estendidas, eleve tronco e pernas simultaneamente, como se remasse, tocando as mãos nos pés. Erro comum: arquear a lombar ao subir, sobrecarregando a coluna.'),
  ('core', 'Abdominal reverso declinado', 'Deitado em banco declinado, segure a barra ou mãos atrás da cabeça, eleve a pelve em direção ao teto, contraindo o abdômen inferior. Erro comum: usar impulso das pernas, balançando o corpo.'),
  ('core', 'Abdominal sentado no cabo', 'Sentado, costas retas, segure a alça do cabo à frente e incline o tronco para frente contra a resistência, contraindo o abdômen. Erro comum: usar impulso dos braços ou curvar a lombar.'),
  ('core', 'Abdominal supra', 'Deitado de costas, pernas estendidas, eleve o tronco até tocar os joelhos, mantendo as mãos atrás da cabeça ou cruzadas no peito. Erro comum: puxar o pescoço com as mãos ou arquear a lombar.'),
  ('core', 'Abdominal V-up', 'Deitado, braços estendidos atrás, levante simultaneamente tronco e pernas formando um V, tentando tocar os pés com as mãos. Erro comum: usar impulso dos quadris ou deixar os joelhos dobrados.'),
  ('core', 'Bird dog', 'Execute em quatro apoios, mantenha a coluna neutra e estenda simultaneamente o braço direito à frente e a perna esquerda para trás, mantendo o quadril nivelado; retorne ao ponto inicial. Erro comum: arquear a lombar ou deixar o quadril cair.'),
  ('core', 'Bottoms up (elevação de quadril deitado)', 'Deite-se supino, pés apoiados no chão, eleve o quadril até alinhar ombros, quadris e joelhos, contraindo os glúteos, depois desça controladamente. Erro comum: deixar o quadril cair rápido ou não ativar o core.'),
  ('core', 'Butt-ups (prancha com elevação de quadril)', 'Na prancha, eleve o quadril formando um V invertido, contraindo os glúteos, e retorne controlado. Erro típico: elevar o quadril demais, perdendo o alinhamento da coluna ou não contrair os glúteos.'),
  ('core', 'Canivete lateral', 'Deitado de lado, apoie o antebraço, eleve tronco e pernas simultaneamente formando um “V” lateral, depois desça controlado. Erro comum: usar impulso dos braços ou deixar o quadril cair, diminuindo o trabalho do core.'),
  ('core', 'Cocoon (recolhimento de joelhos)', 'Deite-se de costas, joelhos dobrados, pés no chão; enrole o abdômen e eleve o tronco aproximando o peito dos joelhos, retornando de forma controlada. Erro comum: usar impulso dos braços ou balançar a pelve, reduzindo a ativação do core.'),
  ('core', 'Cotovelo no joelho (abdominal)', 'Deite-se de costas, eleve as pernas a 90°, toque o cotovelo direito no joelho esquerdo enquanto estende a perna oposta, alternando os lados. Erro comum: puxar o pescoço com as mãos, tirando a carga do abdômen.'),
  ('core', 'Dead bug', 'Deite-se de costas, braços estendidos ao teto e joelhos flexionados 90°, estenda alternadamente braço direito e perna esquerda mantendo a lombar no chão, retorne e troque. Erro comum: arquear a lombar ou mover rapidamente, perdendo controle.'),
  ('core', 'Elevação de joelhos suspensa', 'Pendure-se na barra, mantenha o tronco estável e traga os joelhos ao peito em movimento curvo, depois desça controlado. Erro comum: balançar as pernas ou impulsionar com os quadris.'),
  ('core', 'Elevação de pernas', 'Deite-se supino, pernas estendidas, eleve-as até formar 90° e desça sem tocar o chão, mantendo a lombar firme. Erro comum: curvar a lombar ou impulsionar com as mãos.'),
  ('core', 'Elevação de pernas no banco reto', 'Deite-se num banco reto, segure a borda, levante as pernas retas até 90° e desça controlado. Erro comum: deixar as pernas bater no banco ou arquear a coluna durante o movimento.'),
  ('core', 'Elevação de pernas suspensa', 'Pendure-se na barra, pernas estendidas, eleve-as até 90° ou mais e controle a descida. Erro comum: balançar o corpo ou usar impulso dos ombros.'),
  ('core', 'Elevação pélvica solo', 'Deite-se de costas, pés apoiados no chão, eleve a pelve formando uma linha reta dos ombros aos joelhos, contraindo glúteos no topo. Erro comum: arquear a lombar excessivamente ou não alcançar a extensão completa.'),
  ('core', 'ELEVAÇÃO PÉLVICA SOLO UNI', 'Deite-se de costas, apoie um pé no chão e a outra perna estendida, eleve a pelve mantendo o tronco alinhado, contraindo o glúteo da perna de apoio. Erro comum: deixar o quadril cair ou compensar com a perna estendida.'),
  ('core', 'Figura 8 (kettlebell)', 'Segure o kettlebell com as duas mãos, pés na largura dos ombros, e trace um caminho em forma de oito ao redor do corpo, mantendo o tronco firme. Erro comum: usar impulso dos quadris ou deixar o tronco curvar.'),
  ('core', 'Flexão lateral de tronco (barra)', 'Segure a barra com as duas mãos acima da cabeça, mantenha o tronco ereto e incline o corpo lateralmente, retornando à posição neutra. Erro comum: usar impulso ou curvar a coluna, reduzindo a eficácia.'),
  ('core', 'Flexão lateral de tronco (halter)', 'Segure um haltere com a mão acima da cabeça, mantenha o tronco firme e faça a flexão lateral, retornando ao centro. Erro comum: inclinar exageradamente ou arredondar a lombar, sobrecarregando a coluna.'),
  ('core', 'Flutter kicks', 'Deite-se de costas, mãos sob o quadril, eleve levemente os ombros e faça movimentos alternados de chute, mantendo as pernas retas e o core firme. Erro comum: levantar a cabeça ou curvar a lombar, reduzindo a eficácia.'),
  ('core', 'Heel touch', 'Deite de costas, joelhos flexionados e pés no chão; eleve levemente os ombros e toque o calcanhar direito com a mão direita, depois o esquerdo, alternando. Erro comum: usar impulso balançando a pelve em vez de controlar o movimento.'),
  ('core', 'Hollow body hold', 'Deite-se de costas, levante ombros e pernas do chão, mantenha a lombar colada ao solo e estenda os braços ao lado da cabeça, formando um “V” invertido. Erro comum: deixar a lombar arquear ou as pernas cair.'),
  ('core', 'Hollow body rock', 'Na posição hollow, balance suavemente para frente e para trás mantendo o tronco curvo e a lombar sempre em contato com o chão. Erro comum: perder a rigidez do core, permitindo que a lombar se eleve.'),
  ('core', 'Judo flip no cabo', 'Segure o cabo com ambas as mãos, posicione o corpo em prancha lateral, eleve o quadril e faça um giro controlado, trazendo o cabo em arco sobre o tronco, finalizando com o corpo alinhado. Erro comum: não estabilizar o core, permitindo que o quadril caia.'),
  ('core', 'Knees to elbow', 'Segure a barra com as mãos na largura dos ombros, pendure o corpo e eleve os joelhos até tocar os cotovelos, seguindo um arco controlado. Erro comum: balançar o tronco ou usar impulso, perdendo a tensão abdominal.'),
  ('core', 'L-sit', 'Apoie as mãos ao lado do corpo, eleve o tronco mantendo as pernas estendidas à frente formando um “L”. Erro comum: curvar a lombar ou não manter as pernas totalmente retas, reduzindo a ativação do core.'),
  ('core', 'Landmine 180°', 'Posicione a barra fixa em um ângulo, segure a extremidade livre, gire o tronco 180° mantendo os quadris estáveis e a barra descrevendo um arco. Erro comum: usar o quadril para gerar rotação, aliviando o core.'),
  ('core', 'Leg raise no banco', 'Deite-se no banco, segure as laterais e eleve as pernas retas até formar 90°, depois desça sem tocar o banco, mantendo controle. Erro comum: usar impulso dos braços ou dobrar os joelhos, diminuindo a carga no abdômen.'),
  ('core', 'Mountain climber lento', 'Na prancha, mover os joelhos de forma controlada, aproximando o peito e retornando, mantendo o core firme. Erro comum: usar impulso dos quadris ao invés da força abdominal.'),
  ('core', 'Pallof press (cabo)', 'Fique em pé, pés na largura dos ombros, segure o cabo à altura do peito e empurre para frente mantendo o tronco estável, volte controlado. Erro comum: usar o quadril para gerar força, permitindo rotação do tronco.'),
  ('core', 'Passagem entre as pernas (kettlebell)', 'Em pé, segure o kettlebell com ambas as mãos, agache levemente, gire o tronco e passe o peso de um lado ao outro entre as pernas, mantendo a coluna neutra. Erro comum: girar demais a cintura ou curvar as costas, perdendo estabilidade.'),
  ('core', 'Prancha', 'Deite-se de bruços, apoie antebraços e pontas dos pés no chão, corpo alinhado da cabeça aos calcanhares. Mantenha a posição contraindo abdômen e glúteos. Erro comum: deixar o quadril subir ou descer, perdendo a linha reta.'),
  ('core', 'Prancha (frontal)', 'Apoie as mãos no chão, alinhadas sob os ombros, e os pés na ponta, formando linha reta da cabeça aos calcanhares. Contraia o core e mantenha o tronco firme. Erro comum: arqueamento da lombar ou elevação excessiva do quadril.'),
  ('core', 'Prancha com elevação de perna', 'Na posição de prancha, eleve uma perna mantendo-a reta, alternando os lados, sem perder a estabilidade do tronco. Mantenha o core firme durante a elevação. Erro comum: balançar o quadril ou levantar a perna demais, comprometendo a postura.'),
  ('core', 'Prancha com toque no ombro', 'Na prancha com mãos no chão, levante uma mão e toque o ombro oposto, retornando e alternando os lados, mantendo o corpo estável. Contraia o abdômen para evitar rotação. Erro comum: girar o tronco ou deixar o quadril balançar.'),
  ('core', 'Prancha em antebraço', 'Apoie os antebraços no chão, cotovelos alinhados sob os ombros, e mantenha o corpo em linha reta dos pés à cabeça, contraindo o core. Segure a posição sem deixar o quadril subir. Erro comum: deixar os ombros subir ou o quadril cair, quebrando a postura.'),
  ('core', 'Prancha lateral', 'Deite-se de lado, apoie o antebraço no chão alinhado ao ombro e eleve o quadril, formando uma linha reta da cabeça aos pés, mantendo o corpo firme. Erro comum: deixar o quadril cair ou subir demais, comprometendo a ativação do core.'),
  ('core', 'Recolhimento de pernas sentado', 'Sente-se na ponta de uma cadeira, segure atrás e eleve as pernas estendidas até 90°, depois desça sem tocar o chão. Erro comum: usar balanço ou curvar a lombar.'),
  ('core', 'Rotação de tronco sentado (barra)', 'Sentado no chão, segure a barra com as duas mãos à frente, mantenha as costas retas e gire o tronco de um lado ao outro, conduzindo a barra ao longo da cintura. Erro comum: usar impulso dos quadris em vez do core.'),
  ('core', 'Rotação russa com halter', 'Sentado com os joelhos flexionados, incline levemente o tronco para trás, segure o haltere com as duas mãos e gire o torso de um lado ao outro, tocando o chão. Erro comum: curvar a coluna ou usar impulso das pernas.'),
  ('core', 'Russian twist', 'Sentado, eleve levemente os pés do chão, incline o tronco para trás e gire o torso de um lado ao outro, tocando o chão com as mãos. Erro comum: deixar a lombar curvar ou usar impulso dos braços.'),
  ('core', 'Sit-up parcial (3/4)', 'Deite-se de costas, joelhos flexionados, mãos levemente atrás da cabeça, eleve o tronco até cerca de 75% da posição sentada, controlando a descida. Erro comum: puxar o pescoço com as mãos ou usar impulso dos quadris.'),
  ('core', 'Sit-up tradicional', 'Deite-se de costas, joelhos dobrados, pés no chão, mãos atrás da cabeça ou cruzadas no peito, eleve o tronco até tocar os joelhos, depois volte controlado. Erro comum: puxar o pescoço ou arquear a lombar ao descer.'),
  ('core', 'Spell caster (halteres)', 'Em pé, segure o haltere com ambas as mãos à frente, incline levemente o tronco para trás e gire o torso levando o peso de um lado ao outro, mantendo os pés firmes. Erro comum: balançar o corpo e usar impulso, deixando o abdômen relaxado.'),
  ('core', 'Spider crawl (prancha caminhando)', 'Comece em posição de prancha alta, mantenha o corpo reto e leve um joelho em direção ao cotovelo externo, depois troque, avançando como uma aranha. Erro comum: elevar ou abaixar o quadril, perdendo a linha reta da coluna.'),
  ('core', 'Toes to bar', 'Pendure-se na barra com as mãos na largura dos ombros, contraia o core e eleve as pernas até tocar a barra com os dedos dos pés, controlando a descida. Erro comum: balançar o corpo e usar impulso em vez da força abdominal.'),
  ('core', 'Windmill (kettlebell)', 'Segure o kettlebell com uma mão acima da cabeça, pés afastados na largura dos ombros, gire o tronco para o lado oposto e leve a mão livre em direção ao chão, mantendo a perna de apoio ligeiramente flexionada. Erro comum: deixar o quadril girar ou curvar a coluna, perdendo a estabilidade.'),
  ('core', 'Windmill avançado (kettlebell)', 'Com o kettlebell acima da cabeça, abra as pernas mais que a largura dos ombros, gire o tronco e deslize a mão livre até tocar o pé oposto, mantendo a perna de apoio estendida e o peso centralizado. Erro comum: dobrar o joelho da perna de apoio ou curvar a lombar, comprometendo o movimento.'),
  ('full_body', 'Agachamento de mobilidade', 'Assuma a postura de agachamento profundo, com os pés firmes, quadris para trás e peito aberto, mantendo a coluna neutra enquanto respira. Erro comum: levantar os calcanhares ou curvar a coluna durante a descida.'),
  ('full_body', 'Alcance dos pés deitado', 'Deite-se de costas, pernas estendidas, eleve os pés até tocar as mãos ou o teto, mantendo o tronco firme, e retorne controlado. Erro comum: arquear excessivamente a lombar ou usar impulso dos braços.'),
  ('full_body', 'Alongamento de isquiotibiais 90/90', 'Sentado, pernas dobradas em 90°, uma à frente e outra atrás, incline o tronco sobre a perna da frente mantendo a coluna reta, sentindo alongamento na parte posterior da coxa. Erro comum: curvar a lombar ou forçar o tronco além do limite, provocando dor.'),
  ('full_body', 'Alongamento de lombar em flexão', 'Ajoelhe-se, sente-se sobre os calcanhares e estenda os braços à frente, levando a testa ao chão. Erro comum: arquear a lombar ou não relaxar os quadris, limitando o alongamento.'),
  ('full_body', 'Alongamento de panturrilha em pé', 'Fique em pé, coloque a ponta do pé em uma superfície elevada e deixe o calcanhar descer lentamente, mantendo a perna reta. Erro comum: fazer movimentos bruscos ou forçar a extensão, provocando dor.'),
  ('full_body', 'Alongamento de peito com cotovelos atrás', 'Em pé, una as mãos atrás das costas, estenda os braços e eleve o peito, puxando os cotovelos para cima e para trás. Erro comum: arredondar os ombros ou não manter os braços retos, diminuindo o alongamento.'),
  ('full_body', 'Alongamento de peito na bola suíça', 'Sente-se na bola, caminhe os pés à frente e role até apoiar a parte superior das costas, mantendo os braços estendidos acima da cabeça e abra o peito ao inclinar-se levemente para trás. Erro comum: curvar a lombar demais ou deixar os ombros subir, reduzindo o alongamento.'),
  ('full_body', 'Alongamento de posterior em pé', 'Fique em pé com os pés juntos, incline o tronco à frente a partir dos quadris mantendo a coluna reta e tente alcançar os dedos dos pés. Erro comum: curvar a lombar, o que sobrecarrega a região.'),
  ('full_body', 'Alongamento em abertura (straddle)', 'Sente-se com as pernas bem afastadas e incline o tronco à frente, mantendo a coluna reta e tentando alcançar o chão. Erro comum: curvar a coluna ou dobrar os joelhos, diminuindo a eficácia do alongamento.'),
  ('full_body', 'Anfersen (calcanhar no glúteo)', 'Em pé, dobre o joelho direito e leve o calcanhar ao glúteo, segurando o tornozelo com a mão, mantendo o tronco ereto. Erro comum: inclinar o tronco ou usar impulso ao levantar a perna.'),
  ('full_body', 'Arrasto de trenó com cinto', 'Prenda o cinto ao trenó, adote postura baixa com joelhos flexionados e costas retas; puxe o trenó à frente caminhando com passos curtos e controlados. Erro comum: curvar a coluna ou puxar com os braços em vez das pernas.'),
  ('full_body', 'Arrasto de trenó para trás', 'Com o cinto preso ao trenó, mantenha o tronco ereto, quadris levemente flexionados e dê passos curtos para trás, puxando o trenó sem inclinar o corpo. Erro comum: inclinar o tronco para frente ou apoiar o peso nos calcanhares, reduzindo a força das pernas.'),
  ('full_body', 'Arrasto frontal com press', 'Inicie em agachamento profundo segurando as alças, empurre o trenó à frente enquanto eleva as alças acima da cabeça, mantendo o core firme. Erro comum: perder a postura ao subir ou fazer o press sem estabilizar o tronco, sobrecarregando ombros.'),
  ('full_body', 'Arremesso de baixo (medicine ball)', 'Agarre a medicine ball no chão, agache e, ao subir explosivamente, lance-a para frente e para cima com os braços estendidos. Erro comum: depender só dos braços, sem a extensão completa dos quadris, reduzindo a potência.'),
  ('full_body', 'Arremesso de peito deitado (medicine ball)', 'Deite-se de costas, joelhos dobrados, segure a bola no peito e empurre-a verticalmente ao estender pernas e tronco, soltando-a no ar. Erro comum: não usar a força das pernas e arquear a lombar ao lançar.'),
  ('full_body', 'Arremesso para trás (medicine ball)', 'Segure a medicine ball à altura do peito, faça leve agachamento e jogue-a para trás, sobre o ombro, usando a explosão dos quadris. Erro comum: lançar apenas com os braços, sem a impulsão do quadril, diminuindo alcance.'),
  ('full_body', 'Atlas stone (simulador)', 'Agarre a pedra simulada na cintura, agache e levante usando pernas e costas, ficando em pé antes de colocar a pedra no suporte. Erro comum: curvar a lombar ao levantar e depender só dos braços, aumentando risco de lesão.'),
  ('full_body', 'Bear crawl', 'Comece em posição de quatro apoios, levante levemente os joelhos e avance alternando mão direita e pé esquerdo, mantendo quadris baixos e core firme. Erro típico: elevar demais os quadris ou arrastar os pés.'),
  ('full_body', 'Bear crawl com arrasto de trenó', 'Mantenha a postura de quatro apoios, puxe o trenó enquanto avança alternando mão e pé opostos, quadris baixos e core ativo. Erro frequente: deixar o trenó puxar rápido demais, fazendo os quadris subirem e perder a estabilidade.'),
  ('full_body', 'Box jump', 'Parta de pé, flexione joelhos e balance os braços, salte explosivamente e aterrisse com ambos os pés totalmente sobre a caixa, mantendo postura ereta; então levante. Erro comum: aterrissar com joelhos estendidos ou usar só tornozelos.'),
  ('full_body', 'Box jump em série', 'Realize saltos consecutivos na caixa, pousando e imediatamente saltando novamente, mantendo o tronco firme e o ritmo constante. Erro comum: perder o ritmo e aterrissar desequilibrado ou sem controle.'),
  ('full_body', 'Box jump lateral', 'Posicione-se ao lado da caixa, impulsione lateralmente, cruze a caixa com ambos os pés e aterrisse suavemente, retornando à posição inicial. Erro comum: depender apenas do impulso dos braços ou pousar com um pé fora da caixa.'),
  ('full_body', 'Box skip', 'Alterne saltos rápidos sobre a caixa, pousando um pé de cada vez, mantendo postura ereta e ritmo constante. Erro comum: deixar o joelho interno colapsar ou perder a cadência do movimento.'),
  ('full_body', 'Burpee', 'Inicie em pé, agache, coloque as mãos no chão, chute os pés para trás em prancha, faça flexão opcional, traga os pés ao peito e salte explosivamente. Erro comum: deixar o quadril cair na flexão ou não estender totalmente ao salto.'),
  ('full_body', 'Burpee box jump-over', 'Faça o burpee padrão e, ao saltar, impulsione-se para cima ultrapassando a caixa, aterrissando do outro lado com ambos os pés. Erro frequente: não usar amplitude suficiente, batendo a caixa ou aterrissando com joelhos muito dobrados.'),
  ('full_body', 'Butterfly stretch', 'Sentado, junte as solas dos pés, segure os tornozelos e empurre os joelhos para baixo, inclinando levemente o tronco à frente. Erro comum: deixar os joelhos subir demais ou curvar a coluna.'),
  ('full_body', 'Carioca (deslocamento cruzado)', 'Em posição de semi‑agachamento, avance lateralmente cruzando a perna de trás à frente, alternando a direção a cada passo, mantendo o tronco ereto e os braços balançando. Erro comum: cruzar demais os pés ou deixar o quadril cair, sobrecarregando os joelhos.'),
  ('full_body', 'Cat-cow', 'Fique em quatro apoios, alinhe mãos sob ombros e joelhos sob quadris; ao inspirar arqueie as costas, levantando a cabeça e o cóccix (cow); ao expirar, arredonde a coluna, levando o queixo ao peito (cat). Erro comum: mover apenas a coluna sem envolver o abdômen ou deixar o quadril subir demais.'),
  ('full_body', 'Clean (barra)', 'Segure a barra no chão, levante-a explosivamente usando quadris e pernas, e receba-a nos ombros em posição de rack, finalizando em pé. Erro comum: puxar com os braços antes da extensão completa dos quadris.'),
  ('full_body', 'Clean and jerk (barra)', 'Execute o clean até a posição de rack e, em seguida, faça o dip e a explosão das pernas para empurrar a barra acima da cabeça, bloqueando os braços. Erro comum: não usar a força das pernas no jerk, sobrecarregando os ombros.'),
  ('full_body', 'Clean deadlift (barra)', 'Comece como um deadlift, puxe a barra explosivamente, estenda os quadris e receba-a nos ombros, terminando em pé. Erro comum: curvar a lombar ao levantar, comprometendo a postura.'),
  ('full_body', 'Clean dos blocos (barra)', 'Posicione a barra sobre blocos, inicie o movimento a partir dessa altura, puxe explosivamente e receba nos ombros, finalizando em pé. Erro comum: iniciar com postura baixa demais, reduzindo a potência da elevação.'),
  ('full_body', 'Clean pull (barra)', 'A partir da posição de hang, puxe a barra até a metade da coxa mantendo costas retas, sem chegar ao rack. Erro comum: puxar demais, chegando ao peito e sobrecarregando os ombros.'),
  ('full_body', 'Clean shrug (barra)', 'Comece com a barra no chão, pés na largura dos quadris e pegada pronada; levante-a estendendo quadris e joelhos e, ao subir, faça um encolhimento de ombros mantendo os braços retos. Erro comum: usar os braços para puxar a barra em vez de gerar força com o quadril.'),
  ('full_body', 'Crucifix (sustentação com halteres)', 'Em pé, pés na largura dos ombros, segure os halteres ao lado do corpo, eleve-os lateralmente até a altura dos ombros com ligeiro arco nos cotovelos. Erro comum: levantar os halteres acima dos ombros ou usar impulso do corpo, sobrecarregando a lombar.'),
  ('full_body', 'Círculos de braço', 'Em pé, braços estendidos lateralmente, faça círculos amplos para frente, mantendo os ombros baixos e o tronco estável. Erro comum: elevar os ombros ou fazer círculos pequenos, limitando a mobilidade.'),
  ('full_body', 'Círculos de joelho', 'Em pé, flexione levemente os joelhos e faça movimentos circulares, mantendo o peso distribuído e o tronco ereto. Erro comum: deixar os joelhos colapsarem para dentro ou fazer círculos muito rápidos, perdendo controle.'),
  ('full_body', 'Círculos de punho', 'Sentado ou em pé, estenda os braços à frente, mãos em supinação, gire os punhos descrevendo círculos completos, alternando sentido. Erro comum: mover o antebraço em vez do punho ou forçar amplitude excessiva, causando desconforto.'),
  ('full_body', 'Círculos de quadril em pé', 'Em pé, pés na largura dos ombros, coloque as mãos na cintura e faça círculos amplos com o quadril, mantendo o tronco estável. Erro comum: inclinar o tronco ou usar os joelhos em vez do quadril, reduzindo o trabalho da região.'),
  ('full_body', 'Círculos de tornozelo', 'Eleve o pé do chão e faça círculos com o tornozelo, mantendo a perna estável. Erro comum: mover o joelho ou o quadril, transformando o exercício em movimento de perna.'),
  ('full_body', 'Depth jump', 'Fique em cima da caixa, pés firmes, e ao descer imediatamente salte explosivamente para cima, estendendo quadris, joelhos e tornozelos, aterrissando suavemente com os joelhos flexionados. Erro comum: aterrissar com os joelhos travados ou inclinar o tronco para frente, reduzindo a potência e sobrecarregando os joelhos.'),
  ('full_body', 'Deslocamento lateral no step', 'Posicione-se ao lado do step, dê um passo lateral para cima, trazendo o outro pé para fechar, depois volte ao chão invertendo o movimento, mantendo ritmo constante. Erro comum: inclinar o tronco ou usar impulso excessivo, reduzindo o trabalho dos glúteos e abdômen.'),
  ('full_body', 'Downward dog', 'Comece em posição de prancha, eleve o quadril para cima e para trás formando um V invertido, mantendo mãos e pés firmes e a cabeça entre os braços. Erro comum: dobrar excessivamente os joelhos ou curvar a coluna, diminuindo o alongamento.'),
  ('full_body', 'Elevação de perna para trás (mobilidade)', 'Posicione-se em quadrupedia, levante uma perna dobrada para trás mantendo o tronco alinhado, volte controlado. Erro comum: arquear a lombar ou mover a perna sem controle.'),
  ('full_body', 'Elevação frontal de perna (mobilidade)', 'Em pé, mantenha o tronco ereto; levante a perna estendida à frente até a altura do quadril, controlando o movimento. Erro comum: inclinar o tronco ou dobrar o joelho, reduzindo a mobilidade da cadeia posterior.'),
  ('full_body', 'Elevação lateral de perna (mobilidade)', 'Fique em pé, apoio em uma perna, eleve a outra lateralmente mantendo o tronco ereto, sem inclinar o corpo. Erro comum: usar impulso do tronco ou elevar a perna acima da linha do quadril, perdendo controle.'),
  ('full_body', 'Farmer walk', 'Segure um halter pesado em cada mão, mantenha postura ereta, ombros para trás e caminhe em linha reta, passos firmes. Erro comum: curvar a coluna ou deixar os braços balançarem demais, perdendo estabilidade.'),
  ('full_body', 'Farmer walk (halteres)', 'Pegue dois halteres, mantenha o tronco alinhado, ombros retraídos e caminhe com passos controlados, mantendo a respiração. Erro comum: segurar os halteres muito alto ou muito baixo, comprometendo o equilíbrio.'),
  ('full_body', 'Foam roll adutor', 'Sente-se com as pernas afastadas, coloque o rolo sob a parte interna da coxa e role da virilha ao joelho. Erro comum: usar velocidade alta ou pressão excessiva, provocando dor.'),
  ('full_body', 'Foam roll costas', 'Deite-se de costas, posicione o rolo na região superior/média das costas, apoie a cabeça nas mãos e role das escápulas até a região lombar. Erro comum: rolar diretamente sobre a coluna ou deixar o pescoço sem apoio.'),
  ('full_body', 'Foam roll de isquiotibiais', 'Sente-se, estenda uma perna sobre o rolo e mantenha a outra dobrada, role da região glútea até o joelho. Erro comum: elevar os quadris, perdendo controle e tensionando a lombar.'),
  ('full_body', 'Foam roll de latíssimo', 'Deite-se de lado, coloque o rolo ao longo da lateral do tronco, da axila ao quadril, e role suavemente. Erro comum: pressionar demais as costelas ou não estabilizar o tronco, reduzindo o efeito.'),
  ('full_body', 'Foam roll glúteo', 'Sente-se no rolo, cruze o tornozelo sobre o joelho oposto e role o glúteo do sacro ao alto da coxa. Erro comum: colocar peso excessivo em um lado, gerando desconforto lombar.'),
  ('full_body', 'Foam roll panturrilha', 'Sente-se, posicione o rolo sob a panturrilha, eleve o quadril e role do tornozelo ao joelho. Erro comum: dobrar demais o joelho ou usar peso excessivo, limitando a mobilidade.'),
  ('full_body', 'Foam roll quadríceps', 'Deite-se de bruços, coloque o rolo sob a parte frontal da coxa e role do joelho ao quadril. Erro comum: deixar o quadril levantar, diminuindo a pressão no músculo.'),
  ('full_body', 'Golpes de marreta', 'Adote postura com pés na largura dos ombros, segure o cabo firmemente e, girando o quadril, eleve o martelo acima da cabeça para depois descer em arco controlado até o alvo, repetindo o movimento. Erro comum: usar a lombar em vez do quadril, gerando movimento descoordenado.'),
  ('full_body', 'Hang clean (barra)', 'Comece com a barra no chão, segure-a com as mãos afastadas, faça a flexão de quadril e joelho e, em seguida, puxe explosivamente a barra, recebendo-a nos ombros em posição de agachamento parcial, para depois ficar em pé. Erro comum: usar os braços para puxar em vez de estender totalmente os quadris, comprometendo a pot'),
  ('full_body', 'Hang clean abaixo dos joelhos (barra)', 'Posicione a barra na altura dos meio‑coxa, dobre quadris mantendo a barra próxima ao corpo, então estenda explosivamente e puxe a barra até a altura dos ombros, recebendo-a com cotovelos altos. Erro comum: puxar com os braços antes da extensão completa dos quadris.'),
  ('full_body', 'Hip flexor stretch', 'Ajoelhe-se com um joelho no chão, coloque o outro pé à frente e alinhe o quadril, então empurre suavemente os quadris para frente mantendo a coluna neutra. Erro comum: arquear excessivamente a lombar ou deixar o joelho avançado passar dos dedos.'),
  ('full_body', 'Jerk balance (barra)', 'Comece com a barra na frente dos ombros, pés na largura dos ombros, flexione levemente os joelhos e empurre a barra em linha reta acima da cabeça, terminando com braços estendidos e corpo alinhado. Erro comum: usar impulso dos quadris sem estabilizar a barra, perdendo controle.'),
  ('full_body', 'Kettlebell swing', 'Fique em pé, pés à largura dos ombros, segure o kettlebell com ambas as mãos, faça um hinge nos quadris, impulsione o kettlebell para frente e para cima até a altura dos ombros, mantendo os braços relaxados. Erro comum: usar os braços para levantar o peso, em vez de impulsionar com os quadris.'),
  ('full_body', 'Kettlebell swing americano', 'Mesma postura do swing, mas eleve o kettlebell acima da cabeça em arco completo, mantendo o tronco firme e os quadris estendidos no topo do movimento. Erro comum: arquear excessivamente a lombar ao subir, comprometendo a postura.'),
  ('full_body', 'Kettlebell swing russo', 'Postura similar, porém eleve o kettlebell apenas até a altura dos ombros, controlando o retorno com os quadris e mantendo o core ativado. Erro comum: não alcançar a extensão total dos quadris, reduzindo a potência.'),
  ('full_body', 'Levantamento terra com axle', 'Posicione a barra axle no chão, pés sob a barra, segure firmemente, mantenha costas retas e levante usando quadris e pernas, mantendo a barra próxima ao corpo. Erro comum: curvar a coluna ou depender dos braços para puxar a carga.'),
  ('full_body', 'Log lift (tronco)', 'Segure o tronco com as duas mãos à frente, posicione os pés na largura dos ombros, agache e, mantendo a coluna reta, levante o log até a extensão total dos braços, depois desça controlado. Erro comum: usar os braços para puxar em vez de impulsionar com as pernas.'),
  ('full_body', 'Mobilidade cervical (rotação)', 'Sentado ou em pé, cabeça ereta, gire lentamente a cabeça para a direita até sentir alongamento, volte ao centro e repita para o lado oposto. Erro comum: forçar o movimento ou mover os ombros, gerando tensão no pescoço.'),
  ('full_body', 'Mobilidade de ombro (PVC pass-through)', 'Segure um bastão com as mãos afastadas, braços estendidos, levante sobre a cabeça e traga à frente, mantendo o bastão reto, repita. Erro comum: curvar as costas ou travar os cotovelos, limitando a amplitude.'),
  ('full_body', 'Mobilidade de quadril (90/90)', 'Sentar com pernas dobradas, uma perna à frente com joelho a 90°, outra atrás também a 90°, manter tronco ereto e girar o quadril para frente e para trás. Erro comum: deixar o tronco curvar ou forçar a rotação com a coluna.'),
  ('full_body', 'Mobilidade torácica em quatro apoios', 'Ficar em quatro apoios, mãos sob ombros e joelhos sob quadris, arquear o peito e girar o tronco para um lado, mantendo os quadris estáveis. Erro comum: mover os quadris ou deixar a lombar arredondar.'),
  ('full_body', 'Mountain climber', 'Assumir a prancha alta, levar um joelho ao peito em linha reta e alternar rapidamente, mantendo o quadril nivelado. Erro comum: elevar o quadril ou deslocar os ombros da linha dos pés.'),
  ('full_body', 'Muscle snatch (barra)', 'Segurar a barra com pegada pronada, partir de agachamento parcial e, explosivamente, estender quadris e puxar a barra em linha reta até acima da cabeça, finalizando com braços estendidos. Erro comum: puxar a barra com os braços antes da extensão completa dos quadris.'),
  ('full_body', 'Passe de peito (medicine ball)', 'Em pé, segure a medicine ball ao nível do peito, empurre-a para frente estendendo os braços, depois traga de volta controlando. Erro comum: arquear as costas ou usar impulso dos quadris em vez da força dos braços.'),
  ('full_body', 'Power clean', 'Comece com os pés na largura dos ombros, barra no chão, pegada pronada. Levante explosivamente a barra até os ombros, puxando com os quadris e finalizando com cotovelos elevados. Erro comum: usar demais os braços, não gerar força com os quadris.'),
  ('full_body', 'Power clean dos blocos (barra)', 'Posicione a barra sobre blocos, pés alinhados, segure firme. Execute o movimento explosivo, levantando a barra até a posição de apoio nos ombros, mantendo o tronco ereto. Erro comum: deixar a barra cair antes de subir, falta de extensão completa.'),
  ('full_body', 'Power snatch dos blocos (barra)', 'Com a barra sobre blocos, pés na largura dos ombros, pegada larga. Levante a barra em um único movimento, passando a cabeça e terminando com o braço estendido acima da cabeça, corpo em agachamento parcial. Erro comum: não estender totalmente os quadris, puxar a barra com os braços.'),
  ('full_body', 'Push press atrás da nuca (barra)', 'Segure a barra atrás da nuca, cotovelos apontados para baixo, faça um dip e, ao subir, empurre a barra para cima até estender os braços. Erro comum: deixar a barra escorregar ou sobrecarregar a coluna cervical.'),
  ('full_body', 'Rickshaw carry', 'Segure o objeto pesado com ambas as mãos, mantenha o tronco ereto e caminhe mantendo o core firme e os ombros para trás. Erro comum: deixar o quadril cair ou inclinar o tronco à frente.'),
  ('full_body', 'Roll out / rolinho de coluna', 'Ajoelhe-se, segure a roda ou barra e role para frente estendendo a coluna, mantendo o abdômen contraído, depois retorne puxando com o core. Erro comum: arquear a lombar ou deixar o quadril subir.'),
  ('full_body', 'Rotação completa (medicine ball)', 'Em pé, segure a bola com as duas mãos à frente, gire o tronco levando a bola de um lado ao outro, mantendo quadris estáveis e olhar fixo à frente. Erro comum: mover os quadris excessivamente ou curvar a coluna.'),
  ('full_body', 'Rotação de tronco na bola', 'Sente-se na bola suíça com os pés firmes no chão, mantenha a coluna ereta e gire o tronco para a direita e esquerda, levando as mãos ao lado do corpo. Erro comum: deixar a pelve balançar ou curvar a lombar.'),
  ('full_body', 'Salto afundado', 'Comece em posição de agachamento profundo, impulsione explosivamente para cima, estendendo os braços, e aterrisse suavemente retornando ao agachamento. Erro comum: aterrissar com os joelhos colapsando para dentro.'),
  ('full_body', 'Salto com joelhos ao peito', 'De pé, flexione levemente os joelhos, salte explosivamente trazendo os joelhos até o peito, e aterrisse com os pés alinhados. Erro comum: não elevar os joelhos o suficiente ou cair com os pés descoordenados.'),
  ('full_body', 'Salto estrela', 'Comece em pé, pés juntos, salte explosivamente abrindo braços e pernas formando X no ar, aterrisse suavemente com joelhos flexionados. Erro comum: não controlar a aterrissagem, deixando joelhos travados ou desequilibrado.'),
  ('full_body', 'Salto horizontal parado', 'Posicione os pés na largura dos ombros, agache levemente e salte para frente mantendo o tronco ereto, aterrissando com ambos os pés simultâneos e joelhos dobrados. Erro comum: inclinar o tronco para frente e pousar com os calcanhares primeiro.'),
  ('full_body', 'Salto lateral', 'Fique em pé, pés alinhados, impulsione-se lateralmente usando força dos quadríceps e glúteos, aterrisse com o pé de apoio e o outro tocando levemente, mantendo o corpo alinhado. Erro comum: cruzar as pernas ao pousar, perdendo estabilidade.'),
  ('full_body', 'Salto no banco', 'Fique em frente ao banco, agache e impulsione-se para cima, pousando com ambos os pés sobre o banco, mantendo o tronco reto e joelhos levemente flexionados. Erro comum: usar apenas os braços para subir, reduzindo a força das pernas.'),
  ('full_body', 'Salto rocket', 'Posicione os pés na largura dos ombros, agache e salte explosivamente elevando os joelhos ao peito, braços ajudam no impulso, aterrisse suavemente com joelhos flexionados. Erro comum: não elevar os joelhos o suficiente, diminuindo a eficácia do movimento.'),
  ('full_body', 'Salto tesoura', 'Comece em posição de agachamento, impulsione-se alternando a perna que avança e a que recua, cruzando-as no ar como tesoura, aterrisse com ambos os pés simultâneos. Erro comum: não coordenar o movimento, resultando em aterrissagem desequilibrada.'),
  ('full_body', 'Saltos laterais no cone', 'Posicione cones alinhados, fique ao lado do primeiro, salte lateralmente sobre cada cone mantendo os pés juntos, aterrissando suavemente e continuando o ritmo. Erro comum: deixar os joelhos colapsarem ao tocar o solo, perdendo amortecimento.'),
  ('full_body', 'Saltos sobre barreiras', 'Encare a barreira, agache levemente e salte verticalmente ultrapassando-a, aterrisse com ambos os pés e joelhos flexionados, mantendo o tronco ereto. Erro comum: não elevar o corpo o suficiente, batendo a barra ou aterrissando com os joelhos travados.'),
  ('full_body', 'Sandbag load (carregar saco)', 'Segure o saco com as duas mãos, pés na largura dos ombros, agache mantendo a coluna neutra e levante o saco até a altura dos ombros, estendendo os quadris. Erro comum: usar os braços para puxar o saco, em vez de gerar força com pernas e quadris.'),
  ('full_body', 'Seated forward fold', 'Sentado no chão, pernas estendidas à frente, flexione o tronco à frente, tentando alcançar os pés, mantendo a coluna alongada. Erro comum: curvar a coluna ou forçar o pescoço, perdendo a extensão.'),
  ('full_body', 'Skipping rápido', 'Fique em pé, pés juntos, pule rapidamente alternando os pés, mantendo os joelhos levemente flexionados e os braços em movimento coordenado. Erro comum: aterrissar com os joelhos estendidos ou pular muito alto, cansando rapidamente.'),
  ('full_body', 'Slam acima da cabeça (medicine ball)', 'Fique em pé, pés na largura dos ombros, segure a bola acima da cabeça e, usando quadris e braços, jogue-a explosivamente ao chão, mantendo a trajetória vertical. Erro comum: usar só os braços, sem envolver o quadril, reduzindo potência.'),
  ('full_body', 'Sled push', 'Posicione-se atrás da trenó, mãos na barra, agache levemente e empurre para frente estendendo quadris e joelhos, mantendo a coluna reta. Erro comum: elevar demais o quadril ou inclinar o tronco para trás, perdendo força.'),
  ('full_body', 'Snatch', 'Comece com a barra no chão, pés na largura dos ombros, puxe explosivamente, mantenha a barra próxima ao corpo e receba-a acima da cabeça com os braços estendidos. Erro comum: deixar a barra afastar-se do corpo, desperdiçando energia.'),
  ('full_body', 'Snatch (barra)', 'Segure a barra com pegada larga, posicione-se com pés firmes, levante-a em um movimento único, passando-a perto do tronco e finalize com os braços totalmente estendidos acima. Erro comum: puxar com os braços antes de completar a extensão dos quadris.'),
  ('full_body', 'Snatch balance (barra)', 'Após receber a barra acima da cabeça, flexione levemente os joelhos e empurre o corpo para baixo, permitindo que a barra desça ao nível dos ombros e termine em agachamento completo. Erro comum: não baixar o corpo antes de estabilizar, sobrecarregando os ombros.'),
  ('full_body', 'Snatch deadlift (barra)', 'Fique em pé, barra no chão, pés na largura dos ombros, segure-a com pegada larga e levante mantendo costas retas, focando na extensão dos quadris até a barra passar os joelhos. Erro comum: curvar a lombar ou puxar com os braços, tirando força das pernas.'),
  ('full_body', 'Snatch shrug (barra)', 'Segure a barra com pegada larga, braços estendidos, eleve rapidamente os ombros em um encolhimento, sem dobrar os cotovelos, mantendo a barra fixa. Erro comum: envolver os braços ou girar a barra, reduzindo a ativação do trapézio.'),
  ('full_body', 'Split clean (barra)', 'Com a barra no chão, posicione os pés em split, segure a barra, faça um puxão explosivo até a altura dos ombros e receba a carga com um pé à frente e outro atrás, mantendo o tronco firme. Erro comum: não estender totalmente os quadris e deixar a barra cair ou perder o alinhamento.'),
  ('full_body', 'Split jerk (barra)', 'Com a barra nos ombros, faça um dip curto, exploda para cima e receba a carga acima da cabeça, posicionando um pé à frente e outro atrás em split, mantendo braços estendidos e tronco firme. Erro comum: dip insuficiente ou joelhos que cedem, comprometendo a estabilidade.'),
  ('full_body', 'Standing forward fold', 'Fique em pé, pés juntos, incline o tronco à frente mantendo as pernas esticadas, tente tocar o chão ou as canelas, relaxe a cabeça. Erro comum: dobrar os joelhos ou curvar a lombar, o que diminui o alongamento.'),
  ('full_body', 'Standing side bend', 'Em pé, pés na largura dos ombros, eleve um braço acima da cabeça e incline o tronco lateralmente para o lado oposto, mantendo o quadril estável. Erro comum: curvar a coluna ou usar força dos braços, em vez de alongar o tronco.'),
  ('full_body', 'Stiff pernas afastadas (barra)', 'Adote postura com pés afastados, barra apoiada nos ombros, dobre o quadril mantendo a coluna reta e desça a barra até abaixo dos joelhos, depois retorne. Erro comum: flexionar excessivamente os joelhos ou arredondar a lombar.'),
  ('full_body', 'Subida na corda', 'Segure a corda, coloque um pé sobre ela e eleve o joelho, usando o core para levantar o corpo, alternando as pernas com leve inclinação do tronco. Erro comum: balançar o corpo demais ou depender apenas dos braços.'),
  ('full_body', 'Superman (extensão de lombar)', 'Deite-se de bruços, braços estendidos à frente, eleve simultaneamente braços e pernas, segure um instante e volte controlado. Erro comum: arquear demais a coluna ou levantar apenas os braços.'),
  ('full_body', 'Suspensão unilateral na barra', 'Segure a barra com uma mão, mantenha o corpo alinhado e puxe o peito em direção à barra, controlando a descida. Erro comum: balançar o corpo ou arquear excessivamente a lombar.'),
  ('full_body', 'Swing vertical (halter)', 'Segure o haltere com ambas as mãos, flexione levemente os joelhos e, ao subir, eleve o peso verticalmente até a altura dos ombros, usando impulso do quadril. Erro comum: usar apenas os braços, sem gerar força do quadril, sobrecarregando ombros.'),
  ('full_body', 'Terra romeno com déficit (barra)', 'Fique em um degrau, pés na largura dos quadris, segure a barra com as mãos. Dobre os quadris, mantendo a coluna reta, e abaixe a barra abaixo dos joelhos, depois volte à posição inicial. Erro comum: curvar as costas ou não manter os quadris para trás.'),
  ('full_body', 'Thruster', 'Segure a barra na posição de rack frontal, pés alinhados ao quadril. Agache até que as coxas fiquem paralelas e, ao subir, empurre a barra acima da cabeça em um movimento contínuo. Erro comum: não completar a extensão da perna antes de pressionar, sobrecarregando os ombros.'),
  ('full_body', 'Thruster (barra)', 'Com a barra no rack frontal, posicione os pés firmes e agache mantendo o peito erguido. Ao subir, impulsione a barra para cima, terminando com os braços estendidos. Erro comum: usar apenas os braços, deixando a força das pernas de fora.'),
  ('full_body', 'Tire flip (virar pneu)', 'Fique de frente para o pneu, agache e segure a borda inferior. Levante usando força dos quadris e pernas, girando o corpo para virar o pneu de cabeça para baixo. Erro comum: depender só dos braços, sem envolver os glúteos e as pernas.'),
  ('full_body', 'Turkish get-up', 'Deitado, segure o kettlebell acima da mão, levante o tronco, apoie o braço, posicione a perna, fique em pé mantendo o peso acima e volte controlado. Erro comum: deixar o braço sair da linha vertical ou pular etapas.'),
  ('full_body', 'Vacuum abdominal', 'Em pé ou deitado, inspire profundamente, depois exale e puxe o umbigo em direção à coluna, mantendo a respiração suspensa por alguns segundos. Erro comum: prender a respiração excessivamente ou não contrair o abdômen profundo.'),
  ('full_body', 'Wall ball', 'Posicione-se a cerca de 2 m da parede, segure a bola, agache com coluna reta e, ao subir, projete a bola contra a parede acima da cabeça, receba e repita. Erro comum: curvar a lombar no agachamento ou lançar a bola muito baixa.'),
  ('full_body', 'World''s greatest stretch', 'Comece em posição de afundo, pé direito à frente, coloque as mãos no chão ao lado do pé direito, deslize o joelho esquerdo para fora e gire o tronco levantando o braço esquerdo ao céu. Erro comum: deixar o joelho da frente ultrapassar a linha dos dedos ou não girar o tronco, reduzindo a mobilidade.'),
  ('full_body', 'Yoke walk (caminhada com yoke)', 'Posicione a carga sobre os ombros, mantenha o peito aberto, core firme e dê passos curtos e controlados, evitando inclinar o tronco para frente ou para trás. Erro comum: deixar os ombros subir ou perder a postura ereta, o que sobrecarrega a coluna.'),
  ('legs', 'ABDUÇÃO', 'Sentado na máquina, ajuste a almofada sobre as coxas, empurre as pernas para fora contra a resistência, mantendo o tronco firme. Erro comum: deixar os joelhos se abrir demais ou usar o tronco para impulsionar.'),
  ('legs', 'ADUÇÃO', 'Sentado, coloque a almofada interna nas coxas, traga as pernas para dentro contra a resistência, controlando o movimento. Erro comum: cruzar as pernas ou usar impulso do tronco.'),
  ('legs', 'Adução de quadril com elástico', 'Em pé, elástico preso ao tornozelo ou à perna, cruze a perna sobre a linha central, puxando contra a resistência, mantendo o tronco ereto. Erro comum: inclinar o tronco ou usar impulso da perna de apoio.'),
  ('legs', 'Adução de quadril no cabo', 'Em pé ao lado da estação, prenda o cabo ao tornozelo externo, traga a perna em direção à linha média, controlando a volta, mantendo o quadril estável. Erro comum: balançar o tronco ou usar impulso da perna de apoio.'),
  ('legs', 'Afundo (halteres)', 'Posicione os pés na largura dos quadris, segure os halteres ao lado e dê um passo à frente, baixando até os joelhos formarem ângulo de 90°. Erro comum: deixar o joelho da frente ultrapassar a ponta do pé ou colapsar para dentro.'),
  ('legs', 'Afundo (peso corporal)', 'Fique em pé, dê um passo à frente mantendo o tronco ereto e desça até os joelhos a 90°, depois volte. Erro comum: inclinar o tronco ou deixar o joelho da frente avançar além do pé.'),
  ('legs', 'Afundo caminhando (barra)', 'Com a barra apoiada nos trapézios, dê passos à frente, agachando cada perna mantendo o tronco vertical e a barra alinhada, alternando as pernas. Erro comum: avançar demais a perna ou curvar a lombar.'),
  ('legs', 'Afundo com passagem do peso (kettlebell)', 'Segure o kettlebell à frente do peito, dê um passo à frente e desça em afundo, passando o peso de um braço ao outro ao subir. Erro comum: perder controle do kettlebell ou deixar o joelho interno colapsar.'),
  ('legs', 'Afundo com salto', 'Execute um afundo, ao subir impulsione e troque de perna no ar, aterrissando em afundo com a outra perna. Erro comum: aterrissar com joelhos muito dobrados ou perder o alinhamento corporal.'),
  ('legs', 'Agachamento (halteres)', 'Fique em pé com os pés na largura dos ombros, segure os halteres ao lado e agache até a coxa ficar paralela ao chão, depois volte. Erro comum: curvar a coluna ou deixar os joelhos ultrapassar a linha dos pés.'),
  ('legs', 'Agachamento (Smith)', 'Sob a barra do Smith, posicione os pés à frente da barra, agache mantendo a barra alinhada ao centro do corpo e volte à posição inicial. Erro comum: usar amplitude curta ou deixar os joelhos colapsarem para dentro.'),
  ('legs', 'Agachamento afundado (halteres)', 'Segure halteres ao lado, dê um passo largo à frente e agache mantendo o peso no calcanhar, depois volte e repita com a outra perna. Erro comum: deixar o joelho da frente avançar demais ou perder a postura ereta.'),
  ('legs', 'Agachamento búlgaro (halteres)', 'Posicione o pé da frente firmemente no chão e o outro elevado em um banco, segure halteres ao lado do corpo e agache até a coxa ficar paralela, mantendo o tronco ereto. Erro comum: deixar o joelho da perna de apoio ultrapassar a ponta do pé ou arredondar a lombar.'),
  ('legs', 'Agachamento búlgaro (Smith)', 'Fique em posição de agachamento búlgaro com a barra apoiada nos ombros, desça mantendo o tronco vertical e a barra em movimento reto. Erro comum: inclinar o tronco para frente ou deixar o joelho interno colapsar.'),
  ('legs', 'Agachamento com elástico', 'Pise no centro do elástico, segure as alças ao lado do corpo e execute o agachamento mantendo a tensão constante, retornando à posição inicial. Erro comum: perder a tensão do elástico ou deixar os joelhos abrir excessivamente.'),
  ('legs', 'Agachamento com salto', 'Agache até a coxa ficar paralela ao chão e, em seguida, impulsione explosivamente para saltar, aterrissando suavemente e repetindo o movimento. Erro comum: aterrissar com os joelhos travados ou perder a postura ereta durante o salto.'),
  ('legs', 'Agachamento Frankenstein (barra)', 'Coloque a barra atrás da cabeça, posicione os pés na largura dos ombros e agache mantendo a barra alinhada ao centro do corpo e o tronco reto. Erro comum: deixar a barra avançar à frente ou arredondar a lombar.'),
  ('legs', 'Agachamento frontal (barra)', 'Apoie a barra nos ombros, eleve os cotovelos, agache mantendo o tronco ereto e os joelhos alinhados com os pés. Erro comum: deixar os cotovelos cair ou curvar as costas ao descer.'),
  ('legs', 'Agachamento frontal (dois kettlebells)', 'Segure um kettlebell em cada mão na altura dos ombros, cotovelos apontados para fora, e agache mantendo o tronco vertical e os pés firmes. Erro comum: deixar os kettlebells avançarem à frente ou perder a estabilidade dos cotovelos.'),
  ('legs', 'Agachamento lateral (barra)', 'Posicione os pés mais afastados que a largura dos ombros, barra sobre os trapézios e incline o tronco levemente. Desça flexionando o joelho de um lado, mantendo o quadril alinhado, e volte à posição inicial. Erro comum: deixar o joelho colapsar para dentro ou inclinar o tronco excessivamente.'),
  ('legs', 'Agachamento livre (barra)', 'Posicione os pés na largura dos ombros, barra sobre os trapézios, peito aberto e agache mantendo a coluna neutra, alinhando joelhos com os pés, depois retorne. Erro comum: curvar a lombar ou deixar os joelhos ultrapassar a linha dos dedos.'),
  ('legs', 'Agachamento livre (peso corporal)', 'Fique em pé com os pés na largura dos ombros, braços à frente ou cruzados, e agache mantendo o peito aberto e o peso nos calcanhares, retornando controlado. Erro comum: subir usando impulso dos braços ou deixar os joelhos cederem para dentro.'),
  ('legs', 'Agachamento na cadeira', 'Sente-se na cadeira da máquina, posicione os pés na plataforma, empurre com os calcanhares até estender os joelhos e volte de forma controlada. Erro comum: usar apenas a perna travada ou arredondar a coluna durante o movimento.'),
  ('legs', 'Agachamento olímpico (barra)', 'Coloque a barra sobre os ombros, pés ligeiramente mais abertos que a largura dos ombros, e agache profundo mantendo o tronco ereto, depois levante explosivamente. Erro comum: perder a postura da coluna ou não alcançar profundidade suficiente.'),
  ('legs', 'AGACHAMENTO PÊNDULO', 'Fique em pé, flexione levemente os joelhos e balance o corpo para frente e para trás como um pêndulo, mantendo o controle e a coluna reta. Erro comum: deixar o movimento ficar descoordenado ou curvar a coluna.'),
  ('legs', 'Agachamento sumô (halter)', 'Abra bem os pés, dedos apontando para fora, segure o haltere entre as pernas com ambas as mãos e agache mantendo as costas retas, depois volte. Erro comum: deixar os joelhos cederem para dentro ou curvar a lombar.'),
  ('legs', 'Alongamento de adutor (borboleta)', 'Sentado, soltar as solas dos pés juntas, joelhos caindo para os lados, segurar os pés e pressionar suavemente os joelhos em direção ao chão. Erro comum: forçar os joelhos demais, causando dor, ou curvar a coluna.'),
  ('legs', 'Alongamento de adutor em pé (afastado)', 'Em pé, separar as pernas além da largura dos ombros, inclinar o tronco lateralmente sobre a perna estendida, mantendo o tronco ereto. Erro comum: curvar a coluna ou deixar o joelho da perna de apoio dobrado.'),
  ('legs', 'Alongamento de glúteo deitado (figure 4)', 'Deitado de costas, cruze o tornozelo de uma perna sobre o joelho da outra, puxe a perna de apoio em direção ao peito, sentindo alongamento no glúteo da perna cruzada. Erro comum: deixar o joelho da perna cruzada subir demais, tensionando a lombar.'),
  ('legs', 'Alongamento de glúteo em pé', 'Em pé, apoie o tornozelo de uma perna sobre a coxa contrária, flexione levemente o joelho de apoio e incline o tronco à frente, mantendo o peito aberto. Erro comum: curvar a coluna ou deixar o joelho da perna cruzada abrir para fora.'),
  ('legs', 'Alongamento de isquiotibiais em pé', 'Fique em pé, pés na largura dos quadris, incline o tronco à frente mantendo a coluna reta e tente alcançar os dedos dos pés. Erro comum: curvar as costas ou dobrar demais os joelhos, reduzindo o alongamento.'),
  ('legs', 'Alongamento de isquiotibiais sentado', 'Sente-se no chão com as pernas esticadas, mantenha a coluna neutra e, dobrando nos quadris, aproxime as mãos dos pés. Erro comum: arquear a lombar ou puxar a cabeça, o que diminui a eficácia.'),
  ('legs', 'Alongamento de panturrilha contra parede', 'De frente para a parede, posicione um pé à frente e o outro atrás com o calcanhar no chão, incline o corpo em direção à parede. Erro comum: dobrar o joelho da perna de trás ou levantar o calcanhar, reduzindo o efeito.'),
  ('legs', 'Alongamento de panturrilha no step', 'Coloque a parte frontal do pé em um step, mantenha a perna esticada e deixe o calcanhar cair abaixo do degrau, sentindo o alongamento. Erro comum: dobrar o joelho ou usar peso excessivo, comprometendo a postura.'),
  ('legs', 'Alongamento de quadríceps deitado', 'Deite-se de lado, dobre o joelho da perna superior e segure o tornozelo puxando-o em direção ao glúteo, mantendo o quadril alinhado. Erro comum: girar o quadril para trás, reduzindo o alongamento.'),
  ('legs', 'Alongamento de quadríceps em pé', 'Em pé, apoie-se em um pé, dobre o joelho da outra perna e segure o tornozelo puxando-o em direção ao glúteo, mantendo os joelhos alinhados. Erro comum: inclinar o tronco para frente, tirando a eficácia.'),
  ('legs', 'Alongamento IT band em pé', 'Em pé, cruze a perna direita atrás da esquerda e incline o tronco lateralmente para o lado da perna de trás, sentindo o alongamento na parte externa da coxa. Erro comum: inclinar demais o tronco ou girar o quadril.'),
  ('legs', 'Alongamento piriforme', 'Deite-se, cruze o tornozelo da perna direita sobre o joelho esquerdo e puxe a perna esquerda em direção ao peito, alongando o piriforme. Erro comum: abrir demais o joelho da perna dobrada ou forçar a rotação da coluna.'),
  ('legs', 'Avanço (barra)', 'Com a barra sobre os ombros, dê um passo à frente, flexione ambos joelhos até a coxa ficar paralela ao chão e retorne. Erro comum: deixar o joelho da frente ultrapassar a ponta do pé ou inclinar o tronco para frente.'),
  ('legs', 'Cadeira abdutora', 'Sentado, costas apoiadas, pés na plataforma, empurre as pernas para fora contra a resistência. Erro comum: usar impulso ou não controlar o retorno, deixando o peso cair.'),
  ('legs', 'Cadeira adutora', 'Sentado, pés na almofada, junte as pernas contra a resistência mantendo o tronco firme. Erro comum: deixar os joelhos abrir demais ou usar carga excessiva que compromete a postura.'),
  ('legs', 'Cadeira extensora', 'Sentado, costas retas, tornozelos sob o apoio, estenda as pernas até quase o bloqueio, sem travar o joelho. Erro comum: estender demais travando o joelho ou balançar o tronco.'),
  ('legs', 'Cadeira extensora unilateral', 'Sentado, um pé sob o apoio, estenda a perna até quase travar, mantendo o tronco estável, depois repita do outro lado. Erro comum: usar impulso do tronco ou deixar a carga excessiva causar balanço.'),
  ('legs', 'Cadeira flexora', 'Deitado de bruços, tornozelos sob o rolo, flexione os joelhos trazendo o calcanhar ao glúteo, controlando a volta. Erro comum: levantar a pelve ou usar carga que impede controle total.'),
  ('legs', 'Clean unilateral (kettlebell)', 'Fique em um pé, a kettlebell ao lado; faça flexão de quadril, segure a alça e, ao estender o quadril, eleve o peso até a altura do ombro, depois desça controlado. Erro comum: inclinar o tronco demais, perdendo o alinhamento e sobrecarregando a lombar.'),
  ('legs', 'Coice de glúteo (peso corporal)', 'Posicione-se em quadrúpede, levante uma perna dobrada, empurrando o pé para cima até alinhar com o tronco, depois desça sem tocar o chão. Erro comum: arquear a lombar ou mover o tronco ao invés da perna, diminuindo o trabalho do glúteo.'),
  ('legs', 'Dead clean (kettlebell)', 'Com o kettlebell entre os pés, agache, segure a alça e levante explosivamente estendendo quadris e joelhos, trazendo o kettlebell ao peito em posição de rack. Erro comum: usar apenas os braços ou não manter a coluna neutra, aumentando o risco de lesão.'),
  ('legs', 'Elevação de quadril (ponte)', 'Deite de costas, joelhos dobrados e pés firmes no chão; eleve o quadril até alinhar tronco e coxa, contraindo os glúteos no topo. Erro comum: deixar a lombar arqueada ou não subir o suficiente, reduzindo a ativação.'),
  ('legs', 'Elevação de quadril unilateral', 'Apoie um pé no chão, a outra perna estendida; eleve o quadril mantendo o tronco alinhado, contraindo o glúteo da perna de apoio. Erro comum: girar o tronco ou deixar o quadril cair, comprometendo o equilíbrio.'),
  ('legs', 'EXTENSÃO', 'Sente-se na máquina, ajuste o apoio, segure as alças, estenda os joelhos até a extensão completa sem travar, depois retorne controlado. Erro comum: bloquear o joelho no final do movimento, sobrecarregando a articulação.'),
  ('legs', 'Flexora em pé (máquina)', 'Fique em pé na máquina, prenda a alça ao tornozelo e flexione o joelho levando o calcanhar ao glúteo, depois retorne controlado. Erro comum: usar impulso do tronco ou curvar a lombar, diminuindo o isolamento.'),
  ('legs', 'Flexora na bola suíça', 'Deite-se de bruços sobre a bola suíça, apoie os pés no chão, eleve o quadril contra a bola contraindo os isquiotibiais e volte lentamente. Erro comum: arquear demais a lombar, sobrecarregando a coluna.'),
  ('legs', 'FLEXÃO CADEIRA', 'Sente-se na máquina, posicione os pés na plataforma e empurre contra a resistência estendendo os joelhos até quase travar, controlando a volta. Erro comum: bloquear os joelhos ao final ou curvar a lombar.'),
  ('legs', 'Flexão de quadril com elástico', 'Prenda o elástico ao tornozelo, fique em pé, flexione levemente o joelho de apoio e empurre o quadril para trás contra a resistência, retornando ao início. Erro comum: usar impulso do tronco ou deixar o joelho de apoio dobrar.'),
  ('legs', 'FLEXÃO MESA', 'Sente-se na máquina, posicione os pés na plataforma e empurre estendendo os joelhos até quase travar, depois volte controlado. Erro comum: travar os joelhos ou usar carga excessiva, aumentando risco de lesão.'),
  ('legs', 'Frog pose (sapo)', 'A partir de quatro apoios, abra os joelhos afastando-os, abaixe o quadril em direção ao chão mantendo as mãos sob os ombros; volte à posição inicial empurrando o chão. Erro comum: deixar os joelhos se aproximarem ou elevar o quadril demais.'),
  ('legs', 'GLÚTEO MÁQUINA', 'Sentado na máquina, posicione o apoio sobre os quadris, pressione a plataforma elevando os quadris até a extensão completa e volte controladamente. Erro comum: arquear a lombar ou usar o tronco ao invés dos glúteos.'),
  ('legs', 'Goblet squat', 'Segure o kettlebell próximo ao peito com ambas as mãos, posicione os pés na largura dos ombros e agache mantendo o peito ereto e os joelhos alinhados aos dedos, depois volte à posição de pé. Erro comum: curvar a coluna ou deixar os joelhos avançarem excessivamente.'),
  ('legs', 'GÊMEOS PÊNDULO', 'Em pé, apoie o peso em uma perna, eleve o calcanhar da outra mantendo o joelho levemente flexionado e balance o pé para frente e para trás em movimento controlado. Erro comum: usar impulso exagerado ou travar o joelho, reduzindo a ativação.'),
  ('legs', 'Hack squat', 'Posicione os ombros sob o encosto, coloque os pés na plataforma à frente e, mantendo o tronco encostado, flexione os joelhos descendo até formar ângulo de 90°, então empurre a carga para subir. Erro comum: deixar os joelhos avançarem demais ou curvar a lombar.'),
  ('legs', 'Hang clean (kettlebell)', 'Comece com o kettlebell entre os pés, flexione quadris e joelhos, segure a alça e, ao subir, estenda explosivamente o quadril, puxando o peso até a posição de rack nos ombros, cotovelos elevados. Erro comum: usar a coluna em vez do quadril, arredondando as costas.'),
  ('legs', 'Hip flexor lunge stretch', 'Dê um passo à frente em posição de afundo, mantenha o joelho traseiro no chão e empurre os quadris para frente, sentindo o alongamento no flexor do quadril da perna de trás. Erro comum: inclinar o tronco para frente ou deixar o joelho da frente ultrapassar os dedos.'),
  ('legs', 'Jerk dip (barra)', 'Segure a barra na frente, posicione os pés firmes, faça um dip (flexão de joelhos) mantendo a barra próxima ao corpo e, ao subir, impulsione explosivamente para cima, estendendo os braços. Erro comum: curvar a coluna ao descer, sobrecarregando a lombar.'),
  ('legs', 'Leg press 45°', 'Sente-se no leg press 45°, coloque os pés na plataforma à largura dos ombros e empurre até estender os joelhos sem travar, retornando controlado. Erro comum: travar os joelhos ou deixar a carga excessiva comprometer a postura.'),
  ('legs', 'Leg press horizontal', 'No leg press horizontal, sente-se, posicione os pés na plataforma e empurre mantendo os quadris fixos, estendendo os joelhos sem bloqueio e controlando a volta. Erro comum: deixar os joelhos colapsarem para dentro ou elevar os quadris.'),
  ('legs', 'Levantamento terra na máquina', 'Posicione os pés na largura dos ombros, segure a barra da máquina com as mãos à frente e, mantendo a coluna neutra, empurre o quadril para frente enquanto estende os joelhos, retornando controlado. Erro comum: curvar a lombar ou usar impulso dos braços.'),
  ('legs', 'Levantamento terra no cabo', 'Fique em pé, pés alinhados, segure a alça do cabo entre as pernas, mantenha a coluna reta e, ao puxar, estenda quadris e joelhos até ficar em pé, controlando a volta. Erro comum: deixar o tronco inclinar demais ou puxar com os braços.'),
  ('legs', 'Levantamento terra unilateral (kettlebell)', 'Em pé, apoio o kettlebell no chão ao lado, agache mantendo a coluna neutra, segure o cabo com uma mão e levante o peso, estendendo quadril e joelho, depois volte. Erro comum: perder o equilíbrio e curvar a lombar ao subir.'),
  ('legs', 'Lizard pose (lagarto)', 'Comece em posição de prancha, leve um pé externo ao lado da mão correspondente, mantendo o quadril baixo e o tronco alinhado, segure a posição. Erro comum: deixar o quadril subir ou dobrar o joelho interno.'),
  ('legs', 'Mesa flexora', 'Deite-se de bruços na máquina, alinhe os joelhos ao eixo, segure a barra, flexione os joelhos trazendo os calcanhares ao glúteo e volte controlado. Erro comum: levantar a pelve ou usar impulso, diminuindo o trabalho dos isquiotibiais.'),
  ('legs', 'Monster walk (caminhada com elástico)', 'Colocar o elástico ao redor das pernas acima dos joelhos, agachar levemente e dar passos laterais amplos mantendo tensão constante no elástico. Erro comum: perder a tensão do elástico ou curvar excessivamente os joelhos.'),
  ('legs', 'Panturrilha em pé (barra)', 'Posicione a barra sobre os ombros, fique na ponta dos pés, eleve o calcanhar e desça controlado. Erro comum: descer demais ou balançar o tronco, perdendo a tensão na panturrilha.'),
  ('legs', 'Panturrilha em pé (máquina)', 'Sente-se na máquina, posicione as pontas dos pés na plataforma, eleve os calcanhares e volte lentamente. Erro comum: deixar os joelhos se moverem ou usar impulso, reduzindo o trabalho da panturrilha.'),
  ('legs', 'Panturrilha inversa (Smith)', 'Coloque a barra na parte superior das costas, fique na ponta dos pés com os calcanhares suspensos, eleve o corpo e desça controlado. Erro comum: dobrar excessivamente os joelhos, tirando foco da panturrilha.'),
  ('legs', 'Panturrilha na máquina de press', 'Sente-se na máquina de press, posicione a ponta dos pés na base, empurre usando apenas a panturrilha e retorne sem travar. Erro comum: estender totalmente os joelhos, sobrecarregando a articulação.'),
  ('legs', 'Panturrilha no leg press', 'Deite-se no leg press, coloque a ponta dos pés na plataforma, empurre usando a panturrilha e retorne controlado. Erro comum: empurrar com os quadríceps, usando os joelhos ao invés da panturrilha.'),
  ('legs', 'Panturrilha sentado (barra)', 'Sente-se, coloque a barra sobre os joelhos, posicione a ponta dos pés na base, eleve os calcanhares e desça devagar. Erro comum: arredondar as costas ou usar impulso, comprometendo a contração da panturrilha.'),
  ('legs', 'Panturrilha sentado (máquina)', 'Sente-se na máquina, apoie a parte inferior dos pés na plataforma com os calcanhares suspensos e eleve o peso estendendo os tornozelos. Erro comum: usar carga excessiva e não controlar a descida, limitando a amplitude do movimento.'),
  ('legs', 'Pigeon pose', 'Comece em posição de quatro, deslize um joelho para frente entre as mãos, estenda a outra perna para trás e abaixe o tronco sobre a perna dobrada, mantendo o quadril alinhado. Erro comum: deixar o quadril girar ou forçar o joelho, causando desconforto.'),
  ('legs', 'Pistol squat', 'Fique em pé, estenda uma perna à frente, agache mantendo o tronco ereto e o joelho da perna de apoio alinhado, depois volte à posição inicial. Erro comum: deixar o joelho ultrapassar a linha dos dedos ou perder o equilíbrio, comprometendo a execução.'),
  ('legs', 'Pull through (cabo)', 'De pé, afaste os pés na largura dos ombros, segure a alça do cabo entre as pernas, flexione levemente os joelhos e, com a coluna neutra, puxe o cabo para trás, estendendo o quadril. Erro comum: arquear a lombar ou usar os braços em vez dos glúteos.'),
  ('legs', 'Squat hold (agachamento profundo)', 'Fique em pé, pés à largura dos ombros, agache até a coxa ficar abaixo paralela ao chão, mantenha postura ereta e segure. Erro comum: deixar os joelhos ultrapassar a linha dos dedos ou curvar as costas.'),
  ('legs', 'Step-up (peso corporal)', 'Suba em um degrau com um pé, estenda a perna até ficar em pé sobre o degrau, depois desça controlado, alternando as pernas. Erro comum: usar impulso do tronco ou deixar o joelho interno colapsar ao subir.'),
  ('legs', 'Step-up com elevação de joelho', 'Suba no degrau com um pé, ao estender a perna eleve o joelho da outra perna até a altura do quadril, depois desça e repita alternando. Erro comum: elevar o joelho sem controle ou deixar o tronco inclinar-se para frente.'),
  ('legs', 'Stiff (barra)', 'Em pé, pés na largura dos ombros, segure a barra à frente, mantenha joelhos levemente flexionados, incline o quadril para frente mantendo a coluna reta até sentir alongamento posterior, volte. Erro comum: curvar a lombar ou deixar a barra descer muito abaixo dos joelhos.'),
  ('legs', 'Stiff (halteres)', 'Fique em pé segurando halteres ao lado, com joelhos levemente flexionados; incline o quadril para frente, baixando os pesos ao longo das pernas até sentir alongamento, e volte à posição inicial. Erro comum: curvar a coluna ou dobrar demais os joelhos.'),
  ('legs', 'Stiff (Smith)', 'Posicione-se sob a barra da Smith com pés na largura dos quadris, segure a barra, dobre o quadril mantendo a coluna neutra e desça a barra próximo às canelas, depois eleve o tronco. Erro comum: deixar a barra avançar à frente ou usar as pernas para levantar.'),
  ('shoulders', 'Alongamento de trapézio superior', 'Em pé, entrelace as mãos atrás da cabeça e pressione suavemente o queixo em direção ao peito, sentindo o alongamento na parte superior do trapézio. Erro comum: elevar os ombros, anulando o efeito.'),
  ('shoulders', 'Anti-gravity press (barra)', 'Segure a barra com pegada pronada, eleve-a acima da cabeça com os braços estendidos e controle a descida. Erro comum: arquear excessivamente a lombar ou elevar os ombros durante o movimento.'),
  ('shoulders', 'Arnold press (halteres)', 'Segure os halteres na altura dos ombros, gire as palmas para dentro e empurre-os para cima enquanto as rotações das mãos se completam, terminando com os braços estendidos. Erro comum: usar peso excessivo e perder a rotação ou elevar os ombros.'),
  ('shoulders', 'Arnold press (kettlebell)', 'Comece com o kettlebell na altura do ombro, palmas voltadas para você; empurre acima da cabeça girando as palmas para frente e volte controlando o movimento. Erro comum: usar impulso do tronco e não completar a rotação, sobrecarregando os ombros.'),
  ('shoulders', 'Bradford press em pé (barra)', 'Segure a barra à frente, eleve-a até a altura dos ombros, então empurre-a para cima e para trás em arco, retornando ao ponto inicial; mantenha o core firme. Erro comum: usar peso excessivo e perder controle do arco, sobrecarregando os ombros.'),
  ('shoulders', 'Car drivers (rotação com anilha)', 'Em pé, segure a barra com as duas mãos, mantenha os braços estendidos à frente e gire a barra em círculos horizontais como se fosse um volante. Erro comum: elevar os ombros ou inclinar o tronco, o que diminui a ativação dos deltóides.'),
  ('shoulders', 'Clean and jerk unilateral (kettlebell)', 'Levante o kettlebell até a posição de rack com um braço, faça um pequeno dip e pressione-o acima da cabeça, mantendo o tronco firme. Erro comum: compensar com o tronco, inclinando o corpo e perdendo estabilidade.'),
  ('shoulders', 'Cross-body shoulder stretch', 'Em pé, eleve um braço à altura do ombro, cruze-o sobre o peito e segure-o com o braço oposto, mantendo os ombros relaxados. Erro comum: curvar o tronco ou puxar o braço excessivamente, reduzindo o alongamento da região posterior do ombro.'),
  ('shoulders', 'Crucifixo inverso (máquina)', 'Sente-se na máquina, ajuste as alavancas na altura dos ombros, segure as alças e abra os braços lateralmente mantendo leve flexão dos cotovelos, retornando controlado. Erro comum: estender totalmente os cotovelos, sobrecarregando a articulação.'),
  ('shoulders', 'Crucifixo inverso no cabo', 'Em pé, cruze o corpo ao cabo, segure as alças, mantenha o tronco firme e abra os braços lateralmente até sentir alongamento posterior, depois volte. Erro comum: usar o tronco para impulsionar, tirando foco dos deltos.'),
  ('shoulders', 'Desenvolvimento (barra)', 'Posicione a barra na altura dos ombros, pés firmes, segure com pegada ligeiramente maior que a largura dos ombros; empurre a barra verticalmente até estender totalmente os braços, mantendo o tronco estável. Erro comum: arquear excessivamente a lombar ou avançar os cotovelos, sobrecarregando a coluna.'),
  ('shoulders', 'Desenvolvimento (halteres)', 'Segure um haltere em cada mão na altura dos ombros, cotovelos dobrados, e empurre-os para cima até estender os braços, mantendo os pulsos alinhados; volte controlado. Erro comum: deixar os cotovelos cair para os lados ou balançar o corpo, reduzindo a ativação dos ombros.'),
  ('shoulders', 'Desenvolvimento (máquina)', 'Sente-se na máquina, ajuste o assento para que as alavancas estejam na altura dos ombros, segure as empunhaduras e empurre para cima até estender os braços, controlando a descida. Erro comum: usar impulso do tronco ou ajustar o assento incorretamente, gerando esforço na lombar.'),
  ('shoulders', 'Desenvolvimento alternado (kettlebell)', 'Com um kettlebell em uma mão ao nível do ombro, pés na largura dos ombros, empurre o kettlebell verticalmente até o braço ficar estendido, mantendo o tronco firme; repita alternando os lados. Erro comum: inclinar o tronco para o lado do peso ou balançar o kettlebell, comprometendo a estabilidade.'),
  ('shoulders', 'Desenvolvimento em pé (halteres)', 'Em pé, segure dois halteres na altura dos ombros, cotovelos apontando para baixo, e eleve-os simultaneamente até estender os braços, mantendo o core contraído; desça controlado. Erro comum: arquear a lombar ou deixar os halteres subirem em trajetórias diferentes, desequilibrando a carga.'),
  ('shoulders', 'Desenvolvimento militar (kettlebell)', 'Segure um kettlebell em cada mão na altura dos ombros, pés firmes, e empurre-os para cima até que os braços fiquem totalmente estendidos, mantendo o tronco estável; retorne controlado. Erro comum: usar impulso dos quadris ou deixar os cotovelos se afastarem, sobrecarregando a coluna.'),
  ('shoulders', 'Desenvolvimento militar em pé (barra)', 'Fique em pé, pés na largura dos ombros, segure a barra um pouco mais aberta que os ombros e empurre-a verticalmente até estender os braços, depois desça controladamente até a altura do peito. Erro comum: arquear excessivamente a lombar ou avançar a barra à frente do corpo.'),
  ('shoulders', 'Desenvolvimento no cabo', 'Em pé, de frente para a polia, segure a alça na altura dos ombros, dê um passo pequeno e empurre-a para frente e acima até estender o braço, retornando de forma controlada. Erro comum: usar carga excessiva e perder a estabilidade do tronco, permitindo balanço.'),
  ('shoulders', 'Desenvolvimento sentado (halteres)', 'Sente-se no banco com as costas apoiadas, pés firmes no chão, segure os halteres na altura dos ombros e empurre-os verticalmente até estender os braços, depois desça controladamente. Erro comum: elevar os ombros ou abrir excessivamente os cotovelos, reduzindo a ativação dos deltos.'),
  ('shoulders', 'Desenvolvimento sentado (kettlebell)', 'Sentado, costas apoiadas, segure o kettlebell com as duas mãos na altura dos ombros e empurre-o acima da cabeça até estender os braços, retornando de forma controlada. Erro comum: usar impulso do tronco ou deixar o punho torcer, comprometendo a postura.'),
  ('shoulders', 'Eagle arm stretch', 'Fique em pé, estenda os braços à frente, cruze um sobre o outro e gire as palmas para cima, puxando os cotovelos para trás para abrir o peito. Erro comum: manter os ombros elevados ou não sentir a abertura.'),
  ('shoulders', 'Elevação alternada de deltoides (halteres)', 'Em pé, com joelhos levemente flexionados, segure halteres ao lado e eleve um braço lateralmente até a altura do ombro, volte controlado e alterne. Erro comum: usar peso excessivo, subir acima da linha do ombro ou balançar o tronco.'),
  ('shoulders', 'Elevação de ombros no banco inclinado (halteres)', 'Sente-se num banco inclinado, segure halteres ao lado e eleve os ombros em direção às orelhas, depois abaixe lentamente. Erro comum: rolar os ombros para frente ou usar impulso ao subir.'),
  ('shoulders', 'Elevação frontal (cabo)', 'Segure a alça do cabo com as mãos à frente, braços estendidos; eleve o braço à altura dos ombros mantendo leve flexão nos cotovelos. Erro comum: usar impulso do corpo ou elevar acima da linha dos ombros, sobrecarregando o trapézio.'),
  ('shoulders', 'Elevação frontal (halteres)', 'Segure um haltere em cada mão ao lado do corpo, palmas para dentro; levante os braços à frente até a altura dos ombros, mantendo controle. Erro comum: balançar o tronco ou arquear as costas, tirando carga dos ombros.'),
  ('shoulders', 'Elevação frontal inclinada (halteres)', 'Sentado em banco inclinado, segure halteres ao lado, braços estendidos; eleve-os à frente até a altura dos ombros, mantendo os cotovelos levemente flexos. Erro comum: arquear as costas ou usar impulso dos ombros, comprometendo a carga.'),
  ('shoulders', 'Elevação lateral (cabo)', 'Prenda a alça do cabo na altura do quadril, segure com a mão lateral; eleve o braço lateralmente até a altura do ombro, mantendo ligeira flexão no cotovelo. Erro comum: elevar acima do ombro ou balançar o tronco, sobrecarregando o trapézio.'),
  ('shoulders', 'Elevação lateral (halteres)', 'Fique em pé, segure halteres ao lado, levante os braços até a altura dos ombros com ligeiro arco, mantendo cotovelos levemente flexos. Erro comum: subir os pesos acima da linha dos ombros ou usar impulso do tronco.'),
  ('shoulders', 'Elevação lateral com frontal (halteres)', 'Comece em pé com halteres ao lado, eleve simultaneamente um braço lateralmente e o outro à frente, mantendo os cotovelos levemente dobrados, até a altura dos ombros. Erro comum: movimentar os braços de forma desigual ou arquear a lombar.'),
  ('shoulders', 'Elevação lateral inclinada unilateral (halter)', 'Apoie o peito em um banco inclinado, segure um haltere com a mão pendendo para baixo e levante o braço lateralmente até a altura do ombro, mantendo o cotovelo levemente flexo. Erro comum: balançar o corpo ou subir o peso acima da linha do ombro.'),
  ('shoulders', 'Elevação lateral unilateral (halter)', 'Em pé, segure um haltere ao lado, eleve o braço lateralmente até a altura do ombro, mantendo o tronco estável e cotovelo levemente flexo. Erro comum: usar o tronco para gerar impulso ou elevar o haltere acima da linha do ombro.'),
  ('shoulders', 'Elevação posterior (halteres)', 'Em pé, incline o tronco à frente com halteres nas mãos, braços estendidos, levante-os para trás mantendo ligeira flexão nos cotovelos até a altura dos ombros. Erro comum: arquear a lombar ou elevar os braços acima da linha dos ombros.'),
  ('shoulders', 'Elevação posterior apoiado no banco (halteres)', 'Sente-se no banco com o peito apoiado, segure os halteres pendurados ao lado e eleve-os lateralmente até a altura dos ombros, mantendo os cotovelos levemente flexos. Não balance o tronco nem eleve os ombros; evite usar impulso.'),
  ('shoulders', 'Encolhimento (barra)', 'Em pé, segure a barra com pegada pronada à largura dos ombros, eleve os ombros em direção às orelhas e volte controlado. Não role os ombros para frente nem use impulso dos braços.'),
  ('shoulders', 'Encolhimento (halteres)', 'Em pé, segure um haltere em cada mão ao lado do corpo, eleve os ombros ao máximo e desça lentamente. Não arqueie as costas nem faça o movimento com os braços.'),
  ('shoulders', 'Face pull (cabo)', 'Fique de frente para o cabo, segure a corda com as duas mãos, puxe em direção ao rosto mantendo cotovelos altos e afastados, contraindo as escápulas. Erro comum: deixar os cotovelos caírem, reduzindo a ativação dos posteriores de ombro.'),
  ('shoulders', 'Handstand push-up', 'Entre em parada de mãos encostada na parede, flexione os cotovelos levando a cabeça em direção ao chão e, em seguida, estenda os braços para retornar à posição vertical. Erro comum: arquear a lombar ou perder o alinhamento dos ombros e quadris.'),
  ('shoulders', 'Jerk unilateral (kettlebell)', 'Segure o kettlebell na mão, pés alinhados, agache levemente e, ao subir, empurre o kettlebell em linha reta acima da cabeça, mantendo o tronco firme. Erro comum: balançar o corpo para compensar o peso, perdendo estabilidade.'),
  ('shoulders', 'Pike push-up', 'Comece em posição de flexão com o quadril elevado formando um V invertido, abaixe a cabeça em direção ao chão dobrando os ombros, depois empurre de volta. Erro comum: deixar os cotovelos abrir demais ou curvar a lombar, reduzindo a ativação dos ombros.'),
  ('shoulders', 'PULLEY FRENTE', 'Fique de frente para a máquina, segure as alças com as mãos na altura dos ombros, empurre para frente estendendo os braços até bloquear, mantendo o tronco firme. Erro comum: arquear excessivamente a lombar ou deixar os cotovelos cair.'),
  ('shoulders', 'Push press', 'Posicione a barra nos ombros, pés na largura dos quadris, faça um pequeno dip e, ao subir, estenda explosivamente os braços levando a barra acima da cabeça. Erro comum: usar só os braços, sem o impulso das pernas.'),
  ('shoulders', 'Push press unilateral (kettlebell)', 'Segure o kettlebell na altura do ombro, pé oposto firme, faça um dip e, ao subir, impulsione o kettlebell acima da cabeça, mantendo o tronco estável. Erro comum: inclinar o tronco para compensar, sobrecarregando a lombar.'),
  ('shoulders', 'Remada alta (barra)', 'Em pé, segure a barra com pegada pronada, levante-a até a altura do peito com cotovelos elevados, controlando a descida. Erro comum: elevar os ombros ou impulsionar com as pernas.'),
  ('shoulders', 'Remada na polia baixa até o queixo', 'Em pé, segure a barra baixa, puxe para cima até o nível do queixo, mantendo tronco ereto e cotovelos elevados. Erro comum: elevar os ombros ou usar impulso do corpo.'),
  ('shoulders', 'Remada para deltoide posterior (barra)', 'Em pé, segure a barra com pegada pronada, incline o tronco à frente e puxe a barra para trás, aproximando as escápulas, mantendo os cotovelos elevados. Erro comum: elevar os ombros ou deixar a barra descer demais.'),
  ('shoulders', 'Reverse prayer stretch', 'Fique em pé ou sente-se, leve as mãos para trás, una as palmas com dedos apontando para cima e pressione suavemente os cotovelos. Erro comum: curvar os ombros ou forçar o alongamento além do limite.'),
  ('shoulders', 'Rotação externa (halter)', 'Em pé, segure um haltere com a mão ao lado do corpo, cotovelo dobrado a 90°, gire o braço para fora mantendo o cotovelo próximo ao tronco. Erro comum: elevar o ombro ou mover o tronco ao invés de isolar o ombro.'),
  ('shoulders', 'Scaption (elevação no plano da escápula)', 'Com os pés firmes, segure um haltere em cada mão ao lado do corpo, levante os braços em um ângulo de 30‑45° ao tronco, mantendo as palmas voltadas para baixo, até a altura dos ombros. Erro comum: elevar os braços muito alto ou inclinar o tronco, sobrecarregando o ombro.'),
  ('shoulders', 'Sleeper stretch', 'Deite-se de lado, cotovelo apoiado no chão a 90°, gire o antebraço em direção ao solo, mantendo o ombro relaxado. Erro comum: forçar a rotação com força excessiva, causando dor no ombro.'),
  ('shoulders', 'Turkish get-up estilo afundo (kettlebell)', 'Segure o kettlebell acima da mão, levante o tronco, posicione a perna em afundo, suba mantendo o peso alinhado e retorne ao chão. Erro comum: perder o alinhamento do tronco ou deixar o joelho avançar demais.'),
  ('shoulders', 'Wall slides', 'Encoste as costas na parede, eleve os braços formando um “W” com cotovelos dobrados e deslize-os para cima até estender os cotovelos, mantendo contato constante com a parede. Erro comum: levantar os ombros ou perder a pressão contra a parede.'),
  ('triceps', 'Alongamento de tríceps acima da cabeça', 'Eleve o braço acima da cabeça, dobre o cotovelo e leve a mão às costas, usando a outra mão para pressionar suavemente o cotovelo. Erro comum: curvar o tronco ou usar impulso, reduzindo o alongamento.'),
  ('triceps', 'Alongamento de tríceps com toalha', 'Segure a toalha atrás das costas, uma mão por cima do ombro e a outra por baixo, puxando a toalha para alongar o tríceps. Erro comum: levantar os ombros ou puxar excessivamente, gerando tensão no cotovelo.'),
  ('triceps', 'JM press (barra)', 'Posicione a barra na frente dos ombros, pés firmes, faça um dip curto e, ao subir, pressione a barra verticalmente até estender os braços, mantendo o tronco ereto. Erro comum: deixar os cotovelos caírem à frente, reduzindo a eficiência do tríceps.'),
  ('triceps', 'Mergulho (peso corporal)', 'Com as mãos apoiadas em paralelas ou banco, estenda os braços, dobre os cotovelos descendo o corpo até que os ombros estejam abaixo dos cotovelos, então empurre para subir. Erro comum: deixar os cotovelos abrir demais para os lados.'),
  ('triceps', 'Mergulho em máquina assistida', 'Sentado, segure as alças e empurre para baixo até estender os cotovelos, controlando a subida. Erro comum: abrir demais os cotovelos ou descer excessivamente, sobrecarregando os ombros.'),
  ('triceps', 'Mergulho em paralelas (calistenia)', 'Apoie as mãos nas paralelas, mantenha o corpo reto, desça até os cotovelos formarem 90° e empurre para subir. Erro comum: deixar os ombros subir ou balançar o corpo, reduzindo o foco no tríceps.'),
  ('triceps', 'Mergulho na máquina (dip machine)', 'Sente-se, agarre as alças e empurre para baixo até estender os cotovelos, controlando a volta. Erro comum: usar impulso das pernas ou inclinar o tronco, tirando carga do tríceps.'),
  ('triceps', 'Mergulho no banco', 'Apoie as mãos no banco atrás, pés no chão, desça flexionando os cotovelos até 90° e empurre para subir. Erro comum: deixar os ombros subir ou abrir os cotovelos para os lados, sobrecarregando os ombros.'),
  ('triceps', 'Ring dips', 'Agarre as argolas com os braços estendidos, abaixe o corpo dobrando os cotovelos até que os ombros fiquem abaixo deles e empurre para subir. Erro comum: deixar os ombros subir ou balançar o corpo.'),
  ('triceps', 'Supino pegada fechada (barra)', 'Deitado no banco, segure a barra com as mãos próximas (cerca de 30 cm), abaixe-a até o peito mantendo os cotovelos próximos ao corpo e empurre para cima até estender os braços. Erro comum: deixar os cotovelos se afastarem, sobrecarregando os ombros.'),
  ('triceps', 'Supino pegada fechada (halteres)', 'Deitado, segure os halteres com as mãos próximas, abaixe-os até o peito mantendo os cotovelos junto ao tronco e empurre para cima até estender os braços. Erro comum: abrir demais os cotovelos, diminuindo a ênfase no tríceps.'),
  ('triceps', 'Tríceps coice (halter)', 'Apoie um joelho e a mão no banco, segure o halter com a outra mão, cotovelo dobrado e estenda o braço para trás. Erro comum: mover o tronco ou usar impulso, reduzindo a carga no tríceps.'),
  ('triceps', 'Tríceps coice sentado (halter)', 'Sente-se na borda do banco, tronco inclinado à frente, segure o halter com a mão, cotovelo próximo ao corpo e estenda o braço para trás. Erro comum: elevar o ombro ou balançar o tronco, tirando foco do tríceps.'),
  ('triceps', 'Tríceps com toalha', 'Segure a toalha atrás das costas com ambas as mãos, braços estendidos, e puxe-a para cima contra a resistência do próprio corpo. Erro comum: arredondar os ombros ou usar impulso das pernas, diminuindo a ativação do tríceps.'),
  ('triceps', 'Tríceps corda (pulley)', 'Fique em pé, segure a corda do pulley com as duas mãos, cotovelos fixos ao lado do corpo, e puxe a corda para baixo separando as pontas. Erro comum: deixar os cotovelos se afastarem do corpo, reduzindo a eficácia do exercício.'),
  ('triceps', 'Tríceps francês (halter)', 'Segure o halter com ambas as mãos acima da cabeça, cotovelos dobrados, abaixe o peso atrás da cabeça e depois estenda os braços. Erro comum: abrir os cotovelos ou curvar as costas, sobrecarregando a lombar.'),
  ('triceps', 'Tríceps francês em pé (barra)', 'Segure a barra com pegada estreita acima da cabeça, cotovelos dobrados, abaixe a barra atrás da nuca e estenda os braços. Erro comum: mover os ombros ou deixar a barra cair, comprometendo a segurança.'),
  ('triceps', 'Tríceps francês em pé (halteres)', 'Segure um haltere em cada mão, braços estendidos acima da cabeça, flexione os cotovelos levando os pesos atrás da cabeça e depois estenda. Erro comum: separar os halteres ou arquear a lombar, perdendo a estabilidade.'),
  ('triceps', 'Tríceps na máquina', 'Sente-se, segure as alças na altura dos ombros e empurre para baixo até estender totalmente os braços, retornando controlado. Erro comum: usar carga excessiva e travar os cotovelos, reduzindo a ativação e podendo lesionar.'),
  ('triceps', 'Tríceps na polia baixa', 'Fique em pé, segure a alça da polia baixa com as mãos, mantenha os cotovelos fixos ao lado do corpo e estenda os antebraços para baixo, controlando a volta. Erro comum: mover os ombros ou balançar o tronco, tirando foco do tríceps.'),
  ('triceps', 'Tríceps pulley (barra)', 'Em pé, agarre a barra da polia, mantenha os cotovelos próximos ao tronco e empurre a barra para baixo até os braços ficarem retos, retornando lentamente. Erro comum: abrir os cotovelos para fora, diminuindo a eficácia do exercício.'),
  ('triceps', 'Tríceps pulley pegada inversa', 'Em pé, segure a barra com pegada supinada (palmas para cima), cotovelos ao lado do corpo, e empurre a barra para baixo mantendo os braços retos, voltando com controle. Erro comum: deixar os cotovelos avançarem à frente, sobrecarregando os ombros.'),
  ('triceps', 'Tríceps testa (barra)', 'Deite-se no banco, segure a barra com pegada fechada, braços estendidos acima do peito e flexione os cotovelos levando a barra à testa, depois estenda novamente. Erro comum: abrir os cotovelos lateralmente, reduzindo a carga no tríceps.'),
  ('triceps', 'Tríceps testa (halter)', 'Deite-se no banco, segure o haltere com ambas as mãos acima do peito, flexione os cotovelos levando o peso à testa e estenda os braços. Erro comum: usar amplitude excessiva e curvar as costas, comprometendo a postura.'),
  ('triceps', 'Tríceps testa declinado (barra W)', 'Deite-se em banco declinado, segure a barra W com as mãos, braços estendidos, flexione os cotovelos levando a barra à testa e volte à posição inicial. Erro comum: deixar os ombros subir ou os cotovelos se afastarem, tirando foco do tríceps.'),
  ('triceps', 'Tríceps testa declinado (halteres)', 'Deite-se em banco declinado, segure um haltere em cada mão acima do peito, flexione os cotovelos levando os pesos à testa e estenda os braços. Erro comum: permitir que os halteres se movam independentemente, perdendo controle e eficácia.'),
  ('triceps', 'Tríceps testa no cabo', 'Deitado, segure a barra do cabo acima da cabeça, cotovelos fixos, abaixe a barra em direção à testa e, em seguida, estenda os braços. Erro comum: deixar os cotovelos abrir ou mover a parte superior do corpo.'),
  ('triceps', 'Tríceps unilateral pegada pronada (halter)', 'Em pé, segure o haltere com a palma virada para baixo, braço ao lado do corpo, flexione o cotovelo levando o peso atrás da cabeça e estenda. Erro comum: usar impulso do tronco ou mover o ombro.')
)
update public.exercises e
   set description = n.descricao
  from novas n
  join public.exercise_groups g on g.slug = n.grupo_slug
 where e.group_id = g.id
   and e.name = n.exercicio_nome
   and e.description is null;
